window.SAGE_CHAPTERS = (window.SAGE_CHAPTERS || []).concat([
{
 id: "bd-1", sage: "bharadvaja", n: 1, order: 1301, date: "2026-10-23",
 title: "Born of Two — Bṛhaspati, Mamatā and the Maruts", titleTe: "ఇద్దరి వల్ల పుట్టినవాడు — బృహస్పతి, మమత, మరుత్తులు",
 src: "Bhāgavata 9.20 · Viṣṇu Purāṇa 4.19 · Mahābhārata, Ādi Parva",
 who: ["bharadvajamuni", "brihaspati", "mamata", "utathya", "dirghatamas", "maruts", "angiras"],
 pages: [
  [
   ["p", "Some great people are born into happy homes. {bharadvajamuni|Bharadvāja}, one of the seven great sages of our age, was not. His story begins with a wrong done in the family of {angiras|Aṅgiras} — and the old books tell it openly, because they want us to see that even a hard beginning can lead to a great life.", "కొందరు మహనీయులు సంతోషకరమైన ఇళ్ళలో పుడతారు. మన యుగపు సప్తర్షులలో ఒకరైన {bharadvajamuni|భరద్వాజుడు} అలా పుట్టలేదు. ఆయన కథ {angiras|అంగిరసుని} వంశంలో జరిగిన ఒక తప్పుతో మొదలవుతుంది — కష్టమైన ఆరంభం నుండి కూడా గొప్ప జీవితం రావచ్చని మనం చూడాలని ప్రాచీన గ్రంథాలు దీన్ని దాచకుండా చెబుతాయి."],
   ["p", "Aṅgiras had two famous sons. The elder was {utathya|Utathya}, a great sage. The younger was {brihaspati|Bṛhaspati}, who would become the guru of the gods. Utathya's wife was {mamata|Mamatā}, and she was expecting a child.", "అంగిరసునికి ఇద్దరు ప్రసిద్ధ కుమారులు. పెద్దవాడు {utathya|ఉతథ్యుడు}, గొప్ప ముని. చిన్నవాడు {brihaspati|బృహస్పతి} — తర్వాత దేవతలకు గురువయ్యాడు. ఉతథ్యుని భార్య {mamata|మమత}; ఆమె అప్పుడు గర్భవతి."],
   ["sglink", "The story of the child in the womb: Dīrghatamas", "గర్భంలోని బిడ్డ కథ: దీర్ఘతముడు", "an-4"]
  ],
  [
   ["h", "A Wrong in the Family", "వంశంలో జరిగిన తప్పు"],
   ["p", "One day Bṛhaspati came to his brother's wife, overcome by desire. Mamatā refused him: “I already carry your brother's child. This is not right.” The unborn child himself spoke from the womb and tried to stop him. But Bṛhaspati would not listen. He cursed the child — who was born blind and became the seer {dirghatamas|Dīrghatamas} — and forced himself on Mamatā against her will.", "ఒక రోజు బృహస్పతి కామంతో అన్నగారి భార్య దగ్గరికి వచ్చాడు. మమత ఆయనను నిరాకరించింది: “నా గర్భంలో ఇప్పటికే మీ అన్నగారి బిడ్డ ఉన్నాడు. ఇది ధర్మం కాదు.” గర్భంలోని బిడ్డే మాట్లాడి ఆయనను ఆపడానికి ప్రయత్నించాడు. కానీ బృహస్పతి వినలేదు. ఆ బిడ్డను శపించాడు — ఆ బిడ్డ గుడ్డివాడిగా పుట్టి {dirghatamas|దీర్ఘతముడు} అనే ఋషి అయ్యాడు — మమత ఇష్టానికి వ్యతిరేకంగా ఆమెను బలవంతం చేశాడు."],
   ["p", "The Bhāgavata says that from this a second child was born to Mamatā — Bṛhaspati's son. The texts call it what it was: an act against dharma by a person who should have known better. Even the guru of the gods could fall, and the books do not pretend otherwise.", "దీని వల్ల మమతకు రెండవ బిడ్డ — బృహస్పతి కుమారుడు — పుట్టాడని భాగవతం చెబుతుంది. జరిగినదాన్ని గ్రంథాలు ఉన్నది ఉన్నట్టే చెబుతాయి: బాగా తెలిసి ఉండవలసిన వ్యక్తి చేసిన అధర్మం. దేవతల గురువు కూడా పతనం కావచ్చు; గ్రంథాలు దాన్ని కప్పిపుచ్చవు."],
   ["dyk", "⚖️", "Bṛhaspati is honoured as guru of the gods and as the planet Jupiter — yet the same books that praise him record this wrong. Our tradition does not say great people never err; it says we must see their errors clearly.", "బృహస్పతిని దేవగురువుగా, గురు గ్రహంగా పూజిస్తాం — అయినా ఆయనను కీర్తించే గ్రంథాలే ఈ తప్పునూ నమోదు చేశాయి. మహనీయులు ఎప్పుడూ తప్పు చేయరని మన సంప్రదాయం చెప్పదు; వారి తప్పులను స్పష్టంగా చూడాలని చెబుతుంది."]
  ],
  [
   ["h", "“Bear Him — He Is Born of Two!”", "“ఇద్దరి బిడ్డ — నువ్వే పెంచు!”"],
   ["p", "When the baby was born, neither parent wanted him. Mamatā was afraid her husband would cast her out for bearing another man's child. Bṛhaspati did not want the shame either. So they quarrelled over the little boy. “Foolish woman,” said Bṛhaspati, “*bhara dvājam* — bring up this child, born of two!” “No, Bṛhaspati,” Mamatā answered, “*bhara dvājam* — you bring him up; he is born of two!”", "బిడ్డ పుట్టాక తల్లిదండ్రులు ఇద్దరూ వాణ్ణి కోరుకోలేదు. వేరొకరి బిడ్డను కన్నందుకు భర్త తనను వెళ్ళగొడతాడని మమత భయపడింది. బృహస్పతికి కూడా ఆ అవమానం వద్దు. కాబట్టి ఆ చిన్నారి గురించి ఇద్దరూ వాదించుకున్నారు. “మూర్ఖురాలా,” అన్నాడు బృహస్పతి, “*భర ద్వాజం* — ఇద్దరి వల్ల పుట్టిన ఈ బిడ్డను నువ్వే పెంచు!” “లేదు బృహస్పతీ,” మమత జవాబిచ్చింది, “*భర ద్వాజం* — ఇద్దరి వల్ల పుట్టినవాడు, నువ్వే పెంచు!”"],
   ["p", "In the end both of them walked away and left the newborn alone. But the words they threw at each other stuck to him as his name: Bharadvāja — *bhara*, “bear, bring up,” and *dvāja*, “born of two.” A name given in a quarrel became one of the most honoured names in India.", "చివరికి ఇద్దరూ ఆ పసిబిడ్డను ఒంటరిగా వదిలి వెళ్ళిపోయారు. కానీ వారు ఒకరిపై ఒకరు విసురుకున్న మాటలే వాడి పేరుగా నిలిచాయి: భరద్వాజుడు — *భర* అంటే “పోషించు, పెంచు,” *ద్వాజ* అంటే “ఇద్దరి వల్ల పుట్టినవాడు.” గొడవలో పెట్టిన పేరు భారతదేశంలో అత్యంత గౌరవనీయమైన పేర్లలో ఒకటిగా మారింది."],
   ["dyk", "🏷️", "Nobody in the story chose the name Bharadvāja kindly. Yet millions of families today proudly say “we are of Bharadvāja gotra.” What a person does with his life decides what his name will mean.", "కథలో ఎవరూ ప్రేమతో భరద్వాజ అనే పేరు పెట్టలేదు. అయినా ఈ రోజు లక్షలాది కుటుంబాలు “మాది భరద్వాజ గోత్రం” అని గర్వంగా చెప్పుకుంటాయి. ఒక మనిషి తన జీవితంతో ఏం చేస్తాడో, అదే అతని పేరుకు అర్థం ఇస్తుంది."]
  ],
  [
   ["h", "Raised by the Storm Gods", "తుఫాను దేవతలు పెంచిన బిడ్డ"],
   ["p", "The abandoned baby was not left to die. The {maruts|Maruts} — the bright young storm gods who ride with Indra — found him and took pity on him. They picked him up, carried him away and cared for him. So the boy whom his own parents would not keep grew up in the arms of the gods of wind and rain.", "వదిలేసిన ఆ పసిబిడ్డ చనిపోలేదు. ఇంద్రునితో కలిసి సంచరించే మెరిసే యువ తుఫాను దేవతలైన {maruts|మరుత్తులు} వాణ్ణి చూసి జాలిపడ్డారు. ఎత్తుకుని తీసుకెళ్ళి సంరక్షించారు. సొంత తల్లిదండ్రులు ఉంచుకోని ఆ బాలుడు గాలి వాన దేవతల ఒడిలో పెరిగాడు."],
   ["p", "Why the Maruts? The Viṣṇu Purāṇa and the Bhāgavata tell what they did next: they gave the child to a great king who had lost all his sons — and that is the next chapter. The Ṛgveda, much older, simply calls him Bharadvāja Bārhaspatya, “Bharadvāja, son of Bṛhaspati,” and the storm gods appear again and again in the hymns of his family.", "మరుత్తులే ఎందుకు? తర్వాత వారు ఏం చేశారో విష్ణు పురాణం, భాగవతం చెబుతాయి: కొడుకులందరినీ కోల్పోయిన ఒక గొప్ప రాజుకు ఆ బిడ్డను ఇచ్చారు — అది తర్వాతి అధ్యాయం. ఇంకా ప్రాచీనమైన ఋగ్వేదం ఆయనను కేవలం భరద్వాజ బార్హస్పత్యుడు — “బృహస్పతి కుమారుడైన భరద్వాజుడు” — అని పిలుస్తుంది; ఆయన వంశపు సూక్తాలలో మరుత్తులు మళ్ళీ మళ్ళీ కనిపిస్తారు."],
   ["src", "Bhāgavata Purāṇa 9.20 (Mamatā, Bṛhaspati and the naming); Viṣṇu Purāṇa 4.19; the Matsya and other Purāṇas tell it in nearly the same way. Mahābhārata, Ādi Parva, the story of Dīrghatamas (Bṛhaspati, Mamatā and the child in the womb). The Ṛgveda's index of seers names him Bharadvāja Bārhaspatya.", "భాగవత పురాణం 9.20 (మమత, బృహస్పతి, నామకరణం); విష్ణు పురాణం 4.19; మత్స్య పురాణం మొదలైనవి దాదాపు ఇలాగే చెబుతాయి. మహాభారతం, ఆదిపర్వం, దీర్ఘతముని కథ (బృహస్పతి, మమత, గర్భంలోని బిడ్డ). ఋగ్వేద ఋషి సూచిక ఆయనను భరద్వాజ బార్హస్పత్యుడు అని పేర్కొంటుంది."]
  ]
 ],
 remember: [
  ["{bharadvajamuni|Bharadvāja} was the son of {brihaspati|Bṛhaspati} and {mamata|Mamatā}, born of a wrong Bṛhaspati did to his brother's wife.", "{bharadvajamuni|భరద్వాజుడు} {brihaspati|బృహస్పతి}, {mamata|మమతల} కుమారుడు — అన్నగారి భార్య పట్ల బృహస్పతి చేసిన తప్పు వల్ల పుట్టాడు."],
  ["His name comes from his parents' quarrel: “bhara dvājam” — bring up this child born of two.", "ఆయన పేరు తల్లిదండ్రుల గొడవ నుండి వచ్చింది: “భర ద్వాజం” — ఇద్దరి వల్ల పుట్టిన ఈ బిడ్డను పెంచు."],
  ["Abandoned by both, he was rescued and raised by the {maruts|Maruts}, the storm gods.", "ఇద్దరూ వదిలేస్తే, తుఫాను దేవతలైన {maruts|మరుత్తులు} కాపాడి పెంచారు."]
 ],
 think: ["Bharadvāja's parents both walked away, yet he became one of the greatest sages. Does where we start decide where we end? What helped him, do you think?", "భరద్వాజుని తల్లిదండ్రులు ఇద్దరూ వదిలి వెళ్ళిపోయారు; అయినా ఆయన మహర్షులలో గొప్పవాడయ్యాడు. మనం ఎక్కడ మొదలవుతామో అదే మనం ఎక్కడికి చేరతామో నిర్ణయిస్తుందా? ఆయనకు ఏది సహాయపడిందని మీరు అనుకుంటున్నారు?"]
},
{
 id: "bd-2", sage: "bharadvaja", n: 2, order: 1302, date: "2026-10-23",
 title: "The Son Given to King Bharata", titleTe: "భరత చక్రవర్తికి ఇచ్చిన కుమారుడు",
 src: "Bhāgavata 9.20–21 · Viṣṇu Purāṇa · Mahābhārata, Ādi Parva",
 who: ["bharadvajamuni", "bharatadaushyanti", "dushyanta", "shakuntala", "maruts", "rantideva", "garga"],
 pages: [
  [
   ["p", "{bharatadaushyanti|Bharata}, the son of {dushyanta|Duṣyanta} and {shakuntala|Śakuntalā}, was one of the greatest emperors of old. He conquered the whole earth, performed great sacrifices, and the land itself — Bhārata — still carries his name. But for all his glory, his family was in ruins: he had no son to rule after him.", "{dushyanta|దుష్యంతుడు}, {shakuntala|శకుంతలల} కుమారుడైన {bharatadaushyanti|భరతుడు} ప్రాచీన చక్రవర్తులలో అత్యంత గొప్పవారిలో ఒకడు. భూమి అంతటినీ జయించాడు, మహాయజ్ఞాలు చేశాడు; ఈ దేశం — భారతం — ఈ రోజుకీ ఆయన పేరునే మోస్తోంది. కానీ ఇంత వైభవం ఉన్నా ఆయన కుటుంబం శిథిలమైంది: తన తర్వాత పాలించడానికి కొడుకు లేడు."],
   ["sglink", "Śakuntalā's story begins with Viśvāmitra", "శకుంతల కథ విశ్వామిత్రునితో మొదలవుతుంది", "vm-6"]
  ],
  [
   ["h", "Three Queens and Their Fear", "ముగ్గురు రాణులు, వారి భయం"],
   ["p", "The Bhāgavata tells a dark story. Bharata had three queens, princesses of Vidarbha, and they bore him sons. But Bharata looked at the boys and said, “These are not like me.” The queens were terrified that the king would reject them and their children. And in that fear, they killed their own sons.", "భాగవతం ఒక చీకటి కథ చెబుతుంది. భరతునికి విదర్భ రాకుమార్తెలైన ముగ్గురు రాణులు ఉన్నారు; వారికి కొడుకులు పుట్టారు. కానీ భరతుడు ఆ బాలురను చూసి, “వీరు నా వంటివారు కాదు” అన్నాడు. రాజు తమనూ తమ పిల్లలనూ తిరస్కరిస్తాడని రాణులు భయపడిపోయారు. ఆ భయంలో తమ సొంత కొడుకులనే చంపేశారు."],
   ["p", "So the great emperor's line was cut off — *vitatha*, “in vain, come to nothing.” The Purāṇas tell this without excuse for anyone: a father's careless, proud words, and mothers' terrible fear, together destroyed the children. It is one of the saddest moments in the story of the Bhārata family.", "అలా ఆ మహాచక్రవర్తి వంశం తెగిపోయింది — *వితథం*, “వ్యర్థం, శూన్యం.” ఈ కథను పురాణాలు ఎవరినీ సమర్థించకుండా చెబుతాయి: ఒక తండ్రి అజాగ్రత్తగా, గర్వంగా అన్న మాటలు, తల్లుల భయంకరమైన భయం — రెండూ కలిసి పిల్లలను నాశనం చేశాయి. భరత వంశపు కథలో ఇది అత్యంత విషాదకరమైన ఘట్టాలలో ఒకటి."],
   ["dyk", "💬", "The Mahābhārata tells this part more gently: it says only that Bharata found none of his sons worthy of the throne. The killing of the children comes from the Bhāgavata, and the Viṣṇu Purāṇa tells it the same way.", "మహాభారతం ఈ భాగాన్ని మెత్తగా చెబుతుంది: భరతునికి తన కొడుకులలో ఎవరూ సింహాసనానికి తగినవారు అనిపించలేదని మాత్రమే అంటుంది. పిల్లలను చంపిన విషయం భాగవతం నుండి వస్తుంది; విష్ణు పురాణం కూడా అలాగే చెబుతుంది."]
  ],
  [
   ["h", "The Sacrifice to the Maruts", "మరుత్తులకు యజ్ఞం"],
   ["p", "Wanting an heir, Bharata performed a great sacrifice to the {maruts|Maruts}, called the Marut-stoma. The storm gods were pleased — and they brought him the boy they had been raising: Bharadvāja. “Take this child as your son,” they said. Bharata adopted him gladly.", "వారసుని కోసం భరతుడు మరుత్తులకు మరుత్‌స్తోమం అనే మహాయజ్ఞం చేశాడు. తుఫాను దేవతలు సంతోషించారు — తాము పెంచుతున్న బాలుణ్ణి, భరద్వాజుణ్ణి, ఆయనకు తెచ్చి ఇచ్చారు. “ఈ బిడ్డను నీ కుమారునిగా స్వీకరించు,” అన్నారు. భరతుడు సంతోషంగా దత్తత తీసుకున్నాడు."],
   ["p", "Because he came when Bharata's line had become *vitatha*, “fruitless,” the boy was called Vitatha in the royal family. So the child abandoned by two parents was taken in by gods and then by an emperor — a boy “born of two” who in the end had many who loved him.", "భరతుని వంశం *వితథం* — “ఫలించనిది” — అయిన సమయంలో వచ్చాడు కాబట్టి రాజకుటుంబంలో ఆ బాలుణ్ణి వితథుడు అని పిలిచారు. అలా ఇద్దరు తల్లిదండ్రులు వదిలేసిన బిడ్డను మొదట దేవతలు, తర్వాత ఒక చక్రవర్తి చేరదీశారు — “ఇద్దరి వల్ల పుట్టిన” బాలునికి చివరికి ప్రేమించేవారు ఎందరో దొరికారు."]
  ],
  [
   ["h", "Two Ways of Telling It", "రెండు రకాల కథనాలు"],
   ["p", "The Bhāgavata follows Vitatha's line: his son was Manyu, and from Manyu came several branches. From one came {rantideva|Rantideva}, the king who gave away his last food to hungry strangers. From another came {garga|Garga} and the Gārgyas, kṣatriyas who became brāhmaṇas. From another, after a few generations, came Hastin, who built Hastināpura — the city of the Kurus and the Pāṇḍavas.", "భాగవతం వితథుని వంశాన్ని అనుసరిస్తుంది: ఆయన కుమారుడు మన్యువు; మన్యువు నుండి కొన్ని శాఖలు వచ్చాయి. ఒక శాఖ నుండి ఆకలితో వచ్చిన అపరిచితులకు తన చివరి అన్నం ఇచ్చేసిన {rantideva|రంతిదేవుడు} వచ్చాడు. మరొకదాని నుండి {garga|గర్గుడు}, గార్గ్యులు — క్షత్రియులై పుట్టి బ్రాహ్మణులైనవారు — వచ్చారు. ఇంకొకదాని నుండి కొన్ని తరాల తర్వాత హస్తి వచ్చాడు; ఆయనే కురువుల, పాండవుల నగరమైన హస్తినాపురాన్ని నిర్మించాడు."],
   ["p", "The Mahābhārata tells it differently. There Bharadvāja is not adopted; instead he is the priest who performs a great sacrifice for Bharata, and by Bharadvāja's grace a son named Bhumanyu is born to the king — and the Kuru line runs through Bhumanyu to Hastin. Either way, the family of Bhīṣma, the Pāṇḍavas and the Kauravas owes its very survival to Bharadvāja.", "మహాభారతం వేరేలా చెబుతుంది. అక్కడ భరద్వాజుడు దత్తపుత్రుడు కాదు; భరతుని కోసం మహాయజ్ఞం చేసిన పురోహితుడు. భరద్వాజుని అనుగ్రహం వల్ల రాజుకు భూమన్యువు అనే కుమారుడు పుట్టాడు — కురు వంశం భూమన్యువు ద్వారా హస్తి వరకూ సాగింది. ఏ కథనం తీసుకున్నా, భీష్ముడు, పాండవులు, కౌరవుల వంశం నిలిచి ఉండడానికి కారణం భరద్వాజుడే."],
   ["src", "Bhāgavata Purāṇa 9.20 (Bharata's queens, the Marut-stoma, Vitatha) and 9.21 (Vitatha's descendants, Rantideva, Garga, Hastin); Viṣṇu Purāṇa 4.19; Mahābhārata, Ādi Parva, the genealogy of the Puru line (Bharata, Bharadvāja and Bhumanyu).", "భాగవత పురాణం 9.20 (భరతుని రాణులు, మరుత్‌స్తోమం, వితథుడు), 9.21 (వితథుని వంశం, రంతిదేవుడు, గర్గుడు, హస్తి); విష్ణు పురాణం 4.19; మహాభారతం, ఆదిపర్వం, పూరు వంశావళి (భరతుడు, భరద్వాజుడు, భూమన్యువు)."]
  ]
 ],
 remember: [
  ["{bharatadaushyanti|Bharata}, son of Duṣyanta, lost all his sons; the Bhāgavata says his frightened queens killed them.", "దుష్యంతుని కుమారుడైన {bharatadaushyanti|భరతుడు} కొడుకులందరినీ కోల్పోయాడు; భయపడిన రాణులు వారిని చంపారని భాగవతం చెబుతుంది."],
  ["The {maruts|Maruts} gave Bharadvāja to Bharata as a son, and he was called Vitatha.", "{maruts|మరుత్తులు} భరద్వాజుణ్ణి భరతునికి కుమారునిగా ఇచ్చారు; ఆయనను వితథుడు అన్నారు."],
  ["In the Mahābhārata, Bharadvāja is instead the priest by whose grace Bharata's son Bhumanyu is born.", "మహాభారతంలో అయితే భరద్వాజుడు పురోహితుడు; ఆయన అనుగ్రహంతో భరతుని కుమారుడు భూమన్యువు పుట్టాడు."]
 ],
 think: ["Bharata said a few careless words — “these are not like me” — and terrible things followed. Have you seen careless words cause harm? How can we be more careful?", "భరతుడు అజాగ్రత్తగా కొన్ని మాటలు — “వీరు నా వంటివారు కాదు” — అన్నాడు; భయంకరమైన పరిణామాలు వచ్చాయి. అజాగ్రత్త మాటలు హాని చేయడం మీరు ఎప్పుడైనా చూశారా? మనం ఇంకా జాగ్రత్తగా ఎలా ఉండగలం?"]
},
{
 id: "bd-3", sage: "bharadvaja", n: 3, order: 1303, date: "2026-10-23",
 title: "The Seer of the Sixth Maṇḍala", titleTe: "ఆరవ మండల ద్రష్ట",
 src: "Ṛgveda, Maṇḍala 6 · Sāmaveda",
 who: ["bharadvajamuni", "agni", "indra", "pushan", "sarasvati", "garga", "maruts"],
 pages: [
  [
   ["p", "The Ṛgveda, our oldest book, is arranged in ten Maṇḍalas, or “circles.” Six of them — the second to the seventh — are called the family books, because each belongs to one great family of seers. The sixth Maṇḍala belongs to {bharadvajamuni|Bharadvāja} and his family. Its seventy-five hymns were seen by him, his sons and his descendants.", "మనకున్న అత్యంత ప్రాచీన గ్రంథమైన ఋగ్వేదం పది మండలాలుగా విభజించబడింది. వాటిలో ఆరు — రెండవ నుండి ఏడవ వరకు — కుటుంబ మండలాలు అని పిలువబడతాయి, ఎందుకంటే ఒక్కొక్కటి ఒక్కొక్క మహర్షి కుటుంబానికి చెందినది. ఆరవ మండలం {bharadvajamuni|భరద్వాజునిది}, ఆయన కుటుంబానిది. దానిలోని డెబ్బై అయిదు సూక్తాలను ఆయన, ఆయన కుమారులు, వంశీయులు దర్శించారు."],
   ["p", "The index of seers lists his family beside him: Śaṃyu, Ṛjiśvan, Pāyu, Suhotra, Śunahotra, Nara and {garga|Garga}, among others — all called Bārhaspatya or Bhāradvāja. A whole household of poets, generation after generation, all singing to the same gods.", "ఋషి సూచిక ఆయన పక్కనే ఆయన కుటుంబాన్ని పేర్కొంటుంది: శంయువు, ఋజిశ్వుడు, పాయువు, సుహోత్రుడు, శునహోత్రుడు, నరుడు, {garga|గర్గుడు} మొదలైనవారు — అందరినీ బార్హస్పత్యులు లేదా భారద్వాజులు అంటారు. తరం తర్వాత తరం, ఒకే దేవతలను కీర్తించిన కవుల ఇల్లు అది."],
   ["dyk", "📚", "A ṛṣi does not “write” a hymn. The tradition says he “sees” it — the mantra was always there, and the seer was the first to perceive it. That is why a ṛṣi is called a mantra-draṣṭā, a “seer of mantras.”", "ఋషి సూక్తాన్ని “రచించడు.” “దర్శిస్తాడు” అని సంప్రదాయం చెబుతుంది — మంత్రం ఎప్పుడూ ఉంది; దాన్ని మొదట గ్రహించినవాడు ఋషి. అందుకే ఋషిని మంత్రద్రష్ట అంటారు."]
  ],
  [
   ["h", "“Come, O Agni”", "“రా, అగ్నిదేవా”"],
   ["p", "The sixth Maṇḍala opens with hymns to {agni|Agni}, the fire who carries offerings to the gods. One verse from Bharadvāja's hymns became especially famous. The Sāmaveda — the Veda of song — chose it as its very first verse. Whenever a Sāmaveda singer begins, he begins with Bharadvāja's words:", "ఆరవ మండలం హవిస్సులను దేవతలకు చేర్చే {agni|అగ్నిదేవుని} సూక్తాలతో మొదలవుతుంది. భరద్వాజుని సూక్తాలలోని ఒక మంత్రం ప్రత్యేకంగా ప్రసిద్ధి పొందింది. గానవేదమైన సామవేదం దాన్నే తన మొట్టమొదటి మంత్రంగా ఎంచుకుంది. సామగాయకుడు ఎప్పుడు ప్రారంభించినా, భరద్వాజుని మాటలతోనే ప్రారంభిస్తాడు:"],
   ["sloka", ["అగ్న ఆ యాహి వీతయే గృణానో హవ్యదాతయే ।", "ని హోతా సత్సి బర్హిషి ॥"], ["agna ā yāhi vītaye gṛṇāno havyadātaye |", "ni hotā satsi barhiṣi ||"], "Come, O Agni, to the feast, praised by us, to the giving of offerings. Sit down as our priest on the sacred grass. (Ṛgveda 6.16.10; Sāmaveda 1.1)", "ఓ అగ్నీ, మా స్తుతులు అందుకుని విందుకు రా, హవిస్సులను అందించడానికి రా. మా హోతగా పవిత్రమైన దర్భలపై కూర్చో. (ఋగ్వేదం 6.16.10; సామవేదం 1.1)"],
   ["p", "In another hymn to Agni, Bharadvāja describes the moment of seeing in wonder: a steady light set within us for seeing, the mind the swiftest of all things that fly. His ears and eyes fly open, he says, and his heart's light reaches out — what shall I say, what shall I think? It is one of the earliest descriptions in any language of a poet overwhelmed by a vision.", "అగ్నిపై మరొక సూక్తంలో భరద్వాజుడు దర్శనపు ఆశ్చర్యక్షణాన్ని వర్ణిస్తాడు: చూడడానికి మనలో నిలిపిన ఒక స్థిరమైన వెలుగు; ఎగిరే వాటన్నిటిలో అత్యంత వేగవంతమైనది మనస్సు. నా చెవులూ కళ్ళూ విప్పారుతున్నాయి, హృదయంలోని వెలుగు బయటికి సాగుతోంది — ఏమి చెప్పను, ఏమి ఆలోచించను? అంటాడు. దర్శనంతో ఉక్కిరిబిక్కిరైన కవి గురించి ఏ భాషలోనైనా ఉన్న అత్యంత ప్రాచీన వర్ణనలలో ఇది ఒకటి."]
  ],
  [
   ["h", "Indra, Pūṣan and Sarasvatī", "ఇంద్రుడు, పూషుడు, సరస్వతి"],
   ["p", "Most of the hymns that follow are to {indra|Indra}, the strong god who breaks the forts of enemies and frees the waters. Then comes a small, gentle group of hymns to {pushan|Pūṣan}, the god of roads, who rides a chariot drawn by goats. Bharadvāja's family asks him to keep travellers safe, to guide them to good people, and to find cattle that have strayed — the prayers of people who lived on the move with their herds.", "తర్వాత వచ్చే సూక్తాలలో చాలా వరకు శత్రువుల కోటలను పడగొట్టి జలాలను విడిపించే బలశాలి {indra|ఇంద్రునివి}. తర్వాత మేకలు లాగే రథం ఎక్కే దారుల దేవుడు {pushan|పూషునిపై} చిన్న, మృదువైన సూక్తాల సమూహం వస్తుంది. ప్రయాణికులను క్షేమంగా ఉంచమని, మంచివారి దగ్గరికి దారి చూపమని, తప్పిపోయిన పశువులను వెతికి తెమ్మని భరద్వాజ కుటుంబం ఆయనను ప్రార్థిస్తుంది — మందలతో కలిసి సంచరిస్తూ బతికిన ప్రజల ప్రార్థనలు ఇవి."],
   ["p", "One hymn praises the river {sarasvati|Sarasvatī} as a mighty force: with her waves she breaks down the ridges of the hills, and she is the one who gave King Divodāsa to his father, Vadhryaśva. For Bharadvāja's family, Sarasvatī was a real, roaring river as well as a goddess.", "ఒక సూక్తం {sarasvati|సరస్వతీ} నదిని మహాశక్తిగా కీర్తిస్తుంది: తన అలలతో కొండల గట్లను పడగొడుతుంది; వధ్ర్యశ్వునికి దివోదాస రాజును కుమారునిగా ప్రసాదించినది ఆమే. భరద్వాజ కుటుంబానికి సరస్వతి దేవత మాత్రమే కాదు — ఉధృతంగా ప్రవహించే నిజమైన నది కూడా."],
   ["dyk", "🐐", "Later Purāṇas tell that Pūṣan lost his teeth at Dakṣa's sacrifice, and so is offered soft, ground food. The Ṛgveda already speaks of him eating gruel (karambha) — an old detail the later story explains in its own way.", "దక్ష యజ్ఞంలో పూషుడు దంతాలు కోల్పోయాడని, అందుకే ఆయనకు మెత్తగా రుబ్బిన ఆహారం అర్పిస్తారని తర్వాతి పురాణాలు చెబుతాయి. ఋగ్వేదమే ఆయన కరంభం (జావ) తింటాడని చెబుతుంది — ఆ పాత విషయానికి తర్వాతి కథ తనదైన వివరణ ఇచ్చింది."]
  ],
  [
   ["h", "The Hymn of Weapons", "ఆయుధాల సూక్తం"],
   ["p", "The last hymn of the Maṇḍala, seen by Pāyu of Bharadvāja's family, is unlike any other. It blesses a warrior's equipment one by one as he goes out to fight: the armour, the bow, the bowstring that comes close to the ear and seems to whisper, the quiver full of arrows, the chariot, the horses, the whip, and the leather guard that protects the hand from the string.", "ఈ మండలంలోని చివరి సూక్తం — భరద్వాజ వంశీయుడైన పాయువు దర్శించినది — మరే సూక్తం లాంటిదీ కాదు. యుద్ధానికి బయలుదేరే యోధుని పరికరాలను ఒక్కొక్కటిగా ఆశీర్వదిస్తుంది: కవచం, ధనుస్సు, చెవి దగ్గరికి వచ్చి గుసగుసలాడుతున్నట్టు అనిపించే అల్లెత్రాడు, బాణాలతో నిండిన అమ్ములపొది, రథం, గుర్రాలు, చర్నాకోల, అల్లెత్రాడు దెబ్బ నుండి చేతిని కాపాడే తోలు కవచం."],
   ["p", "So the family of a forest sage gave the Veda its war-song — and, many generations later, gave the Kurus their greatest teacher of arms, Droṇa. Bharadvāja's family knew both the hymn and the bow.", "అలా ఒక వనవాస ముని కుటుంబం వేదానికి యుద్ధ గీతాన్ని ఇచ్చింది — ఎన్నో తరాల తర్వాత కురువులకు వారి గొప్ప ధనుర్విద్యా గురువైన ద్రోణుణ్ణి కూడా ఇచ్చింది. భరద్వాజ కుటుంబానికి మంత్రమూ తెలుసు, ధనుస్సూ తెలుసు."],
   ["dyk", "🪔", "When a family says “our gotra is Bharadvāja,” the pravara recited at ceremonies names three seers: Āṅgirasa, Bārhaspatya, Bhāradvāja — grandfather Aṅgiras, father Bṛhaspati, and Bharadvāja himself.", "“మాది భరద్వాజ గోత్రం” అని ఒక కుటుంబం చెప్పినప్పుడు, శుభకార్యాలలో చెప్పే ప్రవరలో ముగ్గురు ఋషుల పేర్లు వస్తాయి: ఆంగీరస, బార్హస్పత్య, భారద్వాజ — తాత అంగిరసుడు, తండ్రి బృహస్పతి, భరద్వాజుడు స్వయంగా."],
   ["src", "Ṛgveda, Maṇḍala 6: Agni hymns at the opening (the verse above is 6.16.10, also the first verse of the Sāmaveda); the hymn of wonder is 6.9; Indra hymns in the middle; the Pūṣan hymns 6.53–58; Sarasvatī 6.61; the weapons hymn 6.75 (seer Pāyu Bhāradvāja). Seer names from the traditional index of the Ṛgveda (Anukramaṇī).", "ఋగ్వేదం, ఆరవ మండలం: ఆరంభంలో అగ్ని సూక్తాలు (పైన చెప్పిన మంత్రం 6.16.10, సామవేదపు మొదటి మంత్రం కూడా); ఆశ్చర్య సూక్తం 6.9; మధ్యలో ఇంద్ర సూక్తాలు; పూష సూక్తాలు 6.53–58; సరస్వతి 6.61; ఆయుధ సూక్తం 6.75 (ద్రష్ట పాయు భారద్వాజుడు). ఋషుల పేర్లు ఋగ్వేద సంప్రదాయ అనుక్రమణి నుండి."]
  ]
 ],
 remember: [
  ["The sixth Maṇḍala of the Ṛgveda was seen by {bharadvajamuni|Bharadvāja} and his family.", "ఋగ్వేదపు ఆరవ మండలాన్ని {bharadvajamuni|భరద్వాజుడు}, ఆయన కుటుంబం దర్శించారు."],
  ["His verse “agna ā yāhi vītaye” is the very first verse of the Sāmaveda.", "ఆయన మంత్రం “అగ్న ఆ యాహి వీతయే” సామవేదపు మొట్టమొదటి మంత్రం."],
  ["The Bharadvāja pravara is Āṅgirasa, Bārhaspatya, Bhāradvāja.", "భరద్వాజ ప్రవర: ఆంగీరస, బార్హస్పత్య, భారద్వాజ."]
 ],
 think: ["Bharadvāja said the mind is the swiftest of all things that fly. Where did your mind fly today? Can you call it back as quickly?", "ఎగిరే వాటన్నిటిలో మనస్సే అత్యంత వేగవంతమైనదని భరద్వాజుడు అన్నాడు. ఈ రోజు మీ మనస్సు ఎక్కడెక్కడికి ఎగిరింది? అంతే వేగంగా దాన్ని వెనక్కి పిలవగలరా?"]
},
{
 id: "bd-4", sage: "bharadvaja", n: 4, order: 1304, date: "2026-10-23",
 title: "Divodāsa, Bṛbu and the Hungry Years", titleTe: "దివోదాసుడు, బృబువు, ఆకలి రోజులు",
 src: "Ṛgveda, Maṇḍala 6 · Manusmṛti 10",
 who: ["bharadvajamuni", "divodasa", "shambara", "indra", "bribu", "sudas", "manu"],
 pages: [
  [
   ["p", "A Vedic seer did not live apart from the world. He was often a purohita — the priest who stood “in front” of a king, praying for him, advising him and singing his victories. {bharadvajamuni|Bharadvāja} and his family were the priests of {divodasa|Divodāsa}, a king of the Bharata clan.", "వైదిక ఋషి లోకానికి దూరంగా బతకలేదు. తరచూ ఆయన పురోహితుడు — రాజుకు “ముందు” నిలిచి ఆయన కోసం ప్రార్థించేవాడు, సలహా ఇచ్చేవాడు, ఆయన విజయాలను గానం చేసేవాడు. {bharadvajamuni|భరద్వాజుడు}, ఆయన కుటుంబం భరత తెగకు చెందిన {divodasa|దివోదాస} రాజుకు పురోహితులు."],
   ["p", "Divodāsa had a beautiful second name: Atithigva, “the one who goes out to meet guests.” He was famous for his hospitality. In Bharadvāja's hymns he appears as a brave king fighting a powerful enemy, {shambara|Śambara}, who held a hundred strongholds in the mountains.", "దివోదాసునికి ఒక అందమైన రెండో పేరు ఉంది: అతిథిగ్వుడు — “అతిథులకు ఎదురేగేవాడు.” ఆయన ఆతిథ్యానికి ప్రసిద్ధుడు. భరద్వాజుని సూక్తాలలో ఆయన కొండలలో వంద కోటలు ఉన్న బలమైన శత్రువు {shambara|శంబరునితో} పోరాడే వీర రాజుగా కనిపిస్తాడు."]
  ],
  [
   ["h", "Indra Breaks the Hundred Forts", "ఇంద్రుడు వంద కోటలను పడగొట్టాడు"],
   ["p", "Again and again the hymns of the sixth Maṇḍala say: “You, Indra, helped Divodāsa against Śambara. You smashed his stone forts, a hundred of them, for the king who honours guests.” Bharadvāja prayed; the king fought; the poet gave the glory to {indra|Indra}.", "ఆరవ మండల సూక్తాలు మళ్ళీ మళ్ళీ ఇలా చెబుతాయి: “ఇంద్రా, శంబరునికి వ్యతిరేకంగా దివోదాసునికి నువ్వు సహాయం చేశావు. అతిథులను గౌరవించే ఆ రాజు కోసం శంబరుని వంద రాతి కోటలను పగలగొట్టావు.” భరద్వాజుడు ప్రార్థించాడు; రాజు పోరాడాడు; కవి ఆ కీర్తిని {indra|ఇంద్రునికి} ఇచ్చాడు."],
   ["p", "Divodāsa's family went on to greatness. His descendant was {sudas|Sudās}, whose famous Battle of the Ten Kings is sung in the seventh Maṇḍala by Vasiṣṭha. So Bharadvāja served the grandfather's generation, and Vasiṣṭha the grandson's — two great seers guiding one royal house.", "దివోదాసుని వంశం ఇంకా గొప్పదైంది. ఆయన వంశీయుడు {sudas|సుదాసుడు}; అతని ప్రసిద్ధ దశరాజ యుద్ధాన్ని ఏడవ మండలంలో వసిష్ఠుడు గానం చేశాడు. అంటే భరద్వాజుడు తాతల తరానికి, వసిష్ఠుడు మనుమల తరానికి సేవ చేశారు — ఒకే రాజవంశాన్ని ఇద్దరు మహర్షులు నడిపించారు."],
   ["sglink", "Vasiṣṭha and the Battle of the Ten Kings", "వసిష్ఠుడు, దశరాజ యుద్ధం", "va-3"],
   ["dyk", "🏛️", "The Purāṇas also tell of a King Divodāsa of Kāśī, the founder of medicine there. The Ṛgveda's Divodāsa is a king of the Bharatas; whether the two are the same, the old texts do not say clearly.", "కాశీలో వైద్యశాస్త్రాన్ని స్థాపించిన దివోదాస రాజు గురించి కూడా పురాణాలు చెబుతాయి. ఋగ్వేదపు దివోదాసుడు భరత తెగ రాజు; ఇద్దరూ ఒకరేనా అనేది ప్రాచీన గ్రంథాలు స్పష్టంగా చెప్పవు."]
  ],
  [
   ["h", "Thanking the Givers", "దాతలకు కృతజ్ఞత"],
   ["p", "Several hymns of the Bharadvāja family end with a dāna-stuti, a “praise of the gift” — a thank-you to the kings who rewarded the poets with cows, horses and chariots. Divodāsa, Prastoka of the Sṛñjayas and Abhyāvartin Cāyamāna are all thanked by name.", "భరద్వాజ కుటుంబపు కొన్ని సూక్తాలు దానస్తుతితో — “దానాన్ని కీర్తించడం”తో — ముగుస్తాయి. ఆవులు, గుర్రాలు, రథాలు ఇచ్చి కవులను సత్కరించిన రాజులకు అది కృతజ్ఞత. దివోదాసుడు, సృంజయుల ప్రస్తోకుడు, అభ్యావర్తి చాయమానుడు — అందరికీ పేరు పేరునా కృతజ్ఞతలు చెప్పారు."],
   ["p", "The most surprising giver is not a king at all. A hymn of the family praises {bribu|Bṛbu}, a carpenter and a chief among the Paṇis — traders whom the Veda often treats as stingy outsiders. Yet Bṛbu gave freely, and the poet says he stood high above the others, broad like the bank of the Gaṅgā. It is one of only two places in the whole Ṛgveda where the Gaṅgā is named.", "అత్యంత ఆశ్చర్యకరమైన దాత అసలు రాజే కాదు. ఆ కుటుంబపు ఒక సూక్తం {bribu|బృబువును} — ఒక వడ్రంగిని, పణుల నాయకుణ్ణి — కీర్తిస్తుంది. వేదం తరచూ పణులను — వ్యాపారులను — పిసినారులైన బయటివారిగా చూస్తుంది. అయినా బృబువు మనసారా ఇచ్చాడు; అతను మిగతావారి కంటే ఎత్తుగా, గంగా తీరం అంత విశాలంగా నిలిచాడని కవి అంటాడు. ఋగ్వేదం మొత్తంలో గంగ పేరు వచ్చే రెండే రెండు చోట్లలో ఇది ఒకటి."]
  ],
  [
   ["h", "When the Sage Was Starving", "ముని ఆకలితో ఉన్నప్పుడు"],
   ["p", "Why was Bharadvāja so grateful to Bṛbu? The Manusmṛti, in its chapter on what a person may do in times of distress, remembers the story. Bharadvāja, it says, was once starving with his sons in a lonely forest, and he accepted many cows from Bṛbu the carpenter.", "బృబువు పట్ల భరద్వాజునికి అంత కృతజ్ఞత ఎందుకు? ఆపద సమయాల్లో మనిషి ఏం చేయవచ్చో చెప్పే అధ్యాయంలో మనుస్మృతి ఈ కథను గుర్తుచేస్తుంది. ఒకప్పుడు భరద్వాజుడు కొడుకులతో కలిసి నిర్జనమైన అడవిలో ఆకలితో అలమటిస్తూ, బృబువు అనే వడ్రంగి నుండి ఎన్నో ఆవులను స్వీకరించాడని అది చెబుతుంది."],
   ["p", "Manu gives this as an example: a great sage, in real need, took a gift from someone whose gifts a priest would normally refuse — and it was no sin, because his children were hungry. In the same place Manu mentions Viśvāmitra and Vāmadeva, who also did hard things in hard times. Rules bend for the sake of life.", "మను దీన్ని ఉదాహరణగా చెబుతాడు: నిజమైన అవసరంలో ఉన్న మహర్షి, సాధారణంగా పురోహితుడు నిరాకరించే వ్యక్తి నుండి దానం తీసుకున్నాడు — పిల్లలు ఆకలితో ఉన్నారు కాబట్టి అది పాపం కాదు. అదే చోట కష్టకాలంలో కఠినమైన పనులు చేసిన విశ్వామిత్రుణ్ణి, వామదేవుణ్ణి కూడా మను ప్రస్తావిస్తాడు. ప్రాణం కోసం నియమాలు సడలుతాయి."],
   ["sglink", "Viśvāmitra in the famine", "కరువులో విశ్వామిత్రుడు", "vm-12"],
   ["src", "Ṛgveda, Maṇḍala 6: Divodāsa Atithigva and Śambara in many Indra hymns (for example 6.26 and 6.47); gift-praises in 6.27 (Abhyāvartin Cāyamāna) and 6.47 (Prastoka, Divodāsa and others); Bṛbu and the Gaṅgā in 6.45; Sarasvatī and Divodāsa in 6.61. Manusmṛti, chapter 10, on conduct in distress (āpad-dharma), naming Bharadvāja and Bṛbu.", "ఋగ్వేదం, ఆరవ మండలం: ఎన్నో ఇంద్ర సూక్తాలలో దివోదాస అతిథిగ్వుడు, శంబరుడు (ఉదాహరణకు 6.26, 6.47); దానస్తుతులు 6.27 (అభ్యావర్తి చాయమానుడు), 6.47 (ప్రస్తోకుడు, దివోదాసుడు మొదలైనవారు); బృబువు, గంగ 6.45లో; సరస్వతి, దివోదాసుడు 6.61లో. మనుస్మృతి, పదవ అధ్యాయం, ఆపద్ధర్మం — భరద్వాజుడు, బృబువుల ప్రస్తావన."]
  ]
 ],
 remember: [
  ["{bharadvajamuni|Bharadvāja} was priest to King {divodasa|Divodāsa}, whom Indra helped against {shambara|Śambara}.", "{bharadvajamuni|భరద్వాజుడు} {divodasa|దివోదాస} రాజుకు పురోహితుడు; {shambara|శంబరునిపై} ఆ రాజుకు ఇంద్రుడు సహాయం చేశాడు."],
  ["The family's hymns thank generous givers by name — even {bribu|Bṛbu}, a carpenter of the Paṇis.", "ఆ కుటుంబపు సూక్తాలు దాతలకు పేరు పేరునా కృతజ్ఞత చెబుతాయి — పణుల వడ్రంగి {bribu|బృబువుకు} కూడా."],
  ["Manu tells how the starving Bharadvāja accepted cows from Bṛbu — no sin in true distress.", "ఆకలితో ఉన్న భరద్వాజుడు బృబువు నుండి ఆవులను స్వీకరించాడని మను చెబుతాడు — నిజమైన ఆపదలో అది పాపం కాదు."]
 ],
 think: ["Bharadvāja thanked a carpenter in a hymn of the Veda, side by side with kings. Who has helped you that you have never properly thanked?", "భరద్వాజుడు రాజులతో సమానంగా ఒక వడ్రంగికి వేద సూక్తంలో కృతజ్ఞత చెప్పాడు. మీకు సహాయం చేసినా మీరు సరిగ్గా కృతజ్ఞత చెప్పని వారు ఎవరైనా ఉన్నారా?"]
},
{
 id: "bd-5", sage: "bharadvaja", n: 5, order: 1305, date: "2026-10-23",
 title: "Three Lives of Study — the Endless Vedas", titleTe: "మూడు జన్మల అధ్యయనం — అనంతమైన వేదాలు",
 src: "Taittirīya Brāhmaṇa 3.10.11",
 who: ["bharadvajamuni", "indra", "agni", "surya"],
 pages: [
  [
   ["p", "Of all the stories about {bharadvajamuni|Bharadvāja}, the one most loved by teachers comes from the Taittirīya Brāhmaṇa, an old prose book of the Black Yajurveda. It is short, and it is about one thing: how much there is to learn.", "{bharadvajamuni|భరద్వాజుని} గురించిన కథలన్నిటిలో గురువులకు అత్యంత ఇష్టమైనది కృష్ణ యజుర్వేదపు ప్రాచీన గద్య గ్రంథమైన తైత్తిరీయ బ్రాహ్మణం నుండి వస్తుంది. అది చిన్నది; దానిది ఒకే విషయం: నేర్చుకోవలసినది ఎంత ఉందో."],
   ["p", "Bharadvāja, it says, lived three whole lifetimes as a brahmacārī — a student of the Veda. When one life ended, he was given another, and he spent it studying too. Then a third. No family, no kingdom, no rest: only learning, life after life.", "భరద్వాజుడు మూడు పూర్తి జీవితకాలాలు బ్రహ్మచారిగా — వేద విద్యార్థిగా — జీవించాడని అది చెబుతుంది. ఒక జీవితం ముగిశాక మరొకటి లభించింది; దాన్నీ అధ్యయనంలోనే గడిపాడు. తర్వాత మూడవది. కుటుంబం లేదు, రాజ్యం లేదు, విశ్రాంతి లేదు: జన్మ తర్వాత జన్మ, కేవలం అధ్యయనం."]
  ],
  [
   ["h", "Indra's Question", "ఇంద్రుని ప్రశ్న"],
   ["p", "At the end of his third life, Bharadvāja lay old and worn out. {indra|Indra} came to him and said, “Bharadvāja, if I gave you a fourth life, what would you do with it?”", "మూడవ జీవితం చివరలో భరద్వాజుడు వృద్ధుడై, శక్తి క్షీణించి పడుకుని ఉన్నాడు. {indra|ఇంద్రుడు} ఆయన దగ్గరికి వచ్చి అన్నాడు: “భరద్వాజా, నీకు నాలుగో జీవితం ఇస్తే దానితో ఏం చేస్తావు?”"],
   ["p", "Without a moment's thought the old sage answered, “I would live it as a student, and study the Veda.”", "క్షణం కూడా ఆలోచించకుండా ఆ వృద్ధ ముని జవాబిచ్చాడు: “దాన్ని కూడా విద్యార్థిగానే గడుపుతాను, వేదాన్ని అధ్యయనం చేస్తాను.”"],
   ["dyk", "🎓", "A brahmacārī is not only someone who stays unmarried — the word means “one who walks in Brahman,” that is, in the Veda. It is the life of a student, living with the teacher and learning.", "బ్రహ్మచారి అంటే కేవలం పెళ్ళి చేసుకోనివాడు కాదు — “బ్రహ్మంలో (వేదంలో) సంచరించేవాడు” అని అర్థం. గురువు దగ్గర ఉంటూ నేర్చుకునే విద్యార్థి జీవితం అది."]
  ],
  [
   ["h", "Three Mountains and Three Handfuls", "మూడు పర్వతాలు, మూడు పిడికిళ్ళు"],
   ["p", "Then Indra showed him three great shapes, like mountains, which no one had ever known. From each mountain Indra took a single handful. “Bharadvāja,” he said, “these three mountains are the three Vedas. And these three handfuls — this is all that you have learned in your three lifetimes. The rest you have not yet learned.”", "అప్పుడు ఇంద్రుడు ఆయనకు ఇంతవరకు ఎవరూ తెలుసుకోని, పర్వతాల వంటి మూడు మహా రూపాలను చూపించాడు. ఒక్కొక్క పర్వతం నుండి ఒక్కొక్క పిడికెడు తీసుకున్నాడు. “భరద్వాజా,” అన్నాడు, “ఈ మూడు పర్వతాలే మూడు వేదాలు. ఈ మూడు పిడికిళ్ళు — నీ మూడు జీవితాలలో నువ్వు నేర్చుకున్నది ఇంతే. మిగిలినదంతా ఇంకా నేర్చుకోలేదు.”"],
   ["p", "And Indra spoke the words for which this story is remembered: *anantā vai vedāḥ* — “the Vedas are endless.” Three lifetimes of the hardest study, and Bharadvāja had gathered only three handfuls from three mountains.", "ఈ కథ దేని కోసం గుర్తుండిపోయిందో ఆ మాటలను ఇంద్రుడు పలికాడు: *అనంతా వై వేదాః* — “వేదాలు అనంతమైనవి.” మూడు జీవితాల కఠోర అధ్యయనం తర్వాత కూడా భరద్వాజుడు మూడు పర్వతాల నుండి మూడు పిడికిళ్ళు మాత్రమే సేకరించగలిగాడు."],
   ["dyk", "⛰️", "Telugu teachers still tell this story to proud students: “Even Bharadvāja, after three lives, had only three handfuls. How much do you think you know?”", "గర్వపడే విద్యార్థులకు తెలుగు గురువులు ఈ రోజుకీ ఈ కథ చెబుతారు: “మూడు జన్మల తర్వాత కూడా భరద్వాజుని దగ్గర మూడు పిడికిళ్ళే ఉన్నాయి. నీకు ఎంత తెలుసనుకుంటున్నావు?”"]
  ],
  [
   ["h", "The Fire That Is All Knowledge", "సర్వ జ్ఞానమైన అగ్ని"],
   ["p", "But Indra did not leave him in despair. “Come,” he said, “know this fire. It is all knowledge.” And he taught Bharadvāja the Sāvitra fire — a special way of building the sacred fire-altar, dedicated to Savitṛ, the shining {surya|Sun}. Bharadvāja learned it, built it, and through it he reached the world of heaven and went to be with the Sun. He did not need a fourth life after all.", "కానీ ఇంద్రుడు ఆయనను నిరాశలో వదలలేదు. “రా,” అన్నాడు, “ఈ అగ్నిని తెలుసుకో. ఇదే సర్వ జ్ఞానం.” ప్రకాశించే {surya|సూర్యుడైన} సవితకు అంకితమైన సావిత్ర అగ్నిని — పవిత్ర అగ్నివేదికను నిర్మించే ఒక ప్రత్యేక విధానాన్ని — భరద్వాజునికి నేర్పాడు. భరద్వాజుడు దాన్ని నేర్చుకుని, నిర్మించి, దాని ద్వారా స్వర్గలోకాన్ని చేరి సూర్యునితో ఏకమయ్యాడు. చివరికి నాలుగో జీవితం అవసరమే రాలేదు."],
   ["p", "The Brāhmaṇa's lesson has two halves. First: no one ever finishes learning — be humble. Second: endless learning is not the goal by itself; there is a knowing that brings the whole of it together, and that is what sets a person free.", "ఈ బ్రాహ్మణ కథ బోధనకు రెండు భాగాలు. మొదటిది: ఎవరూ నేర్చుకోవడం ఎప్పటికీ పూర్తి చేయలేరు — వినయంగా ఉండు. రెండవది: అంతులేని అధ్యయనమే గమ్యం కాదు; అంతటినీ ఒక్కటిగా కలిపే ఒక జ్ఞానం ఉంది — అదే మనిషిని ముక్తుణ్ణి చేస్తుంది."],
   ["src", "Taittirīya Brāhmaṇa 3.10.11 (Kṛṣṇa Yajurveda), in the section on the Sāvitra fire (sāvitra-cayana). The phrase “anantā vai vedāḥ” — “the Vedas are endless” — comes from this passage.", "తైత్తిరీయ బ్రాహ్మణం 3.10.11 (కృష్ణ యజుర్వేదం), సావిత్ర చయనం గురించిన భాగం. “అనంతా వై వేదాః” — “వేదాలు అనంతమైనవి” — అనే వాక్యం ఈ భాగం నుండే వచ్చింది."]
  ]
 ],
 remember: [
  ["{bharadvajamuni|Bharadvāja} spent three whole lifetimes as a student of the Veda.", "{bharadvajamuni|భరద్వాజుడు} మూడు పూర్తి జీవితాలను వేద విద్యార్థిగా గడిపాడు."],
  ["{indra|Indra} showed him three mountains — the Vedas — and three handfuls: all he had learned. “The Vedas are endless.”", "{indra|ఇంద్రుడు} ఆయనకు మూడు పర్వతాలను — వేదాలను — చూపి, మూడు పిడికిళ్ళు — ఆయన నేర్చుకున్నదంతా — చూపించాడు. “వేదాలు అనంతమైనవి.”"],
  ["Indra then taught him the Sāvitra fire, by which he reached the Sun.", "తర్వాత ఇంద్రుడు సావిత్ర అగ్నిని నేర్పాడు; దాని ద్వారా ఆయన సూర్యుణ్ణి చేరాడు."]
 ],
 think: ["If someone offered you a fourth life — or even one free year — what would you spend it learning?", "మీకు ఎవరైనా నాలుగో జీవితం — కనీసం ఒక ఖాళీ సంవత్సరం — ఇస్తే, దాన్ని ఏం నేర్చుకోవడానికి వినియోగిస్తారు?"]
},
{
 id: "bd-6", sage: "bharadvaja", n: 6, order: 1306, date: "2026-10-23",
 title: "Bringing Āyurveda Down From Heaven", titleTe: "స్వర్గం నుండి ఆయుర్వేదాన్ని తెచ్చినవాడు",
 src: "Caraka Saṃhitā, Sūtrasthāna 1",
 who: ["bharadvajamuni", "indra", "ashvins", "daksha", "brahma", "punarvasu", "agnivesha"],
 pages: [
  [
   ["p", "The Caraka Saṃhitā, the great book of Āyurveda, begins not with medicine but with a story — the story of how medicine came to us. And the hero of that story is {bharadvajamuni|Bharadvāja}.", "ఆయుర్వేద మహాగ్రంథమైన చరక సంహిత వైద్యంతో కాదు, ఒక కథతో మొదలవుతుంది — వైద్యం మనకు ఎలా వచ్చిందో చెప్పే కథ. ఆ కథకు నాయకుడు {bharadvajamuni|భరద్వాజుడు}."],
   ["p", "Long ago, it says, diseases arose among living beings. They were obstacles to everything good: to tapas, to fasting and vows, to study, to a life of dharma. A sick body could not pray, could not learn, could not serve. People were dying before their time.", "చాలా కాలం క్రితం ప్రాణులలో రోగాలు పుట్టాయని అది చెబుతుంది. అవి ప్రతి మంచి పనికీ ఆటంకమయ్యాయి: తపస్సుకు, ఉపవాసాలకు, వ్రతాలకు, అధ్యయనానికి, ధర్మబద్ధమైన జీవితానికి. రోగంతో ఉన్న శరీరం ప్రార్థించలేదు, నేర్చుకోలేదు, సేవ చేయలేదు. మనుషులు ఆయువు తీరకముందే చనిపోతున్నారు."],
   ["dyk", "🩺", "The Caraka Saṃhitā says health is the root of dharma, wealth, desire and liberation — all four goals of life. You cannot pursue any of them without it.", "ధర్మ, అర్థ, కామ, మోక్షాలనే నాలుగు పురుషార్థాలకూ ఆరోగ్యమే మూలమని చరక సంహిత చెబుతుంది. అది లేకుండా వాటిలో దేన్నీ సాధించలేం."]
  ],
  [
   ["h", "The Gathering in the Himālayas", "హిమాలయాలలో సమావేశం"],
   ["p", "Moved by pity for all creatures, the great sages gathered on a holy slope of the Himālayas. The Caraka Saṃhitā names many of them — Aṅgiras, Jamadagni, Vasiṣṭha, Kaśyapa, Bhṛgu, Ātreya, Gautama, Pulastya, Nārada, Agastya, Vāmadeva, Mārkaṇḍeya and others. They asked one another: what can be done?", "ప్రాణులన్నిటిపై జాలితో మహర్షులు హిమాలయాల పవిత్ర వాలుపై సమావేశమయ్యారు. చరక సంహిత వారిలో ఎందరి పేర్లో చెబుతుంది — అంగిరసుడు, జమదగ్ని, వసిష్ఠుడు, కశ్యపుడు, భృగువు, ఆత్రేయుడు, గౌతముడు, పులస్త్యుడు, నారదుడు, అగస్త్యుడు, వామదేవుడు, మార్కండేయుడు మొదలైనవారు. “ఏం చేయవచ్చు?” అని ఒకరినొకరు అడిగారు."],
   ["p", "In their meditation they saw the answer: the knowledge of healing was with {indra|Indra}, king of the gods. It had come down a long line — from {brahma|Brahmā} to {daksha|Dakṣa}, from Dakṣa to the twin {ashvins|Aśvins}, the physicians of heaven, and from the Aśvins to Indra. Someone had to go to heaven and ask for it.", "ధ్యానంలో వారికి సమాధానం కనిపించింది: వైద్య జ్ఞానం దేవరాజైన {indra|ఇంద్రుని} దగ్గర ఉంది. అది ఒక దీర్ఘ పరంపరగా వచ్చింది — {brahma|బ్రహ్మ} నుండి {daksha|దక్షునికి}, దక్షుని నుండి స్వర్గ వైద్యులైన కవల {ashvins|అశ్వినీ దేవతలకు}, వారి నుండి ఇంద్రునికి. ఎవరో ఒకరు స్వర్గానికి వెళ్ళి దాన్ని అడగాలి."],
   ["p", "Then Bharadvāja stood up. “Let me be the one,” he said. “Send me.”", "అప్పుడు భరద్వాజుడు లేచి నిలబడ్డాడు. “నేనే వెళ్తాను,” అన్నాడు. “నన్ను పంపండి.”"]
  ],
  [
   ["h", "Learning From Indra", "ఇంద్రుని దగ్గర నేర్చుకోవడం"],
   ["p", "Bharadvāja went to Indra's heaven and found the king of the gods shining among the devas. He bowed and said, “Disease has come to the world of men. Teach me the knowledge of long life, so that I can take it back.” Indra saw that this sage was asking not for himself but for everyone, and he gladly taught him.", "భరద్వాజుడు ఇంద్రుని స్వర్గానికి వెళ్ళి దేవతల మధ్య ప్రకాశిస్తున్న దేవరాజును చూశాడు. నమస్కరించి అన్నాడు: “మానవ లోకానికి రోగాలు వచ్చాయి. దీర్ఘాయువు గురించిన జ్ఞానాన్ని నాకు నేర్పండి — దాన్ని తిరిగి తీసుకెళ్తాను.” ఈ ముని తన కోసం కాకుండా అందరి కోసం అడుగుతున్నాడని చూసి ఇంద్రుడు సంతోషంగా నేర్పాడు."],
   ["p", "What Indra taught is called the *tri-sūtra*, the “three threads” of Āyurveda: the causes of disease (hetu), its signs (liṅga), and its remedies (auṣadha) — for the healthy and for the sick alike. Bharadvāja grasped it all quickly, the book says, with a mind sharpened by long study.", "ఇంద్రుడు నేర్పినదాన్ని ఆయుర్వేదపు *త్రిసూత్రం* — “మూడు సూత్రాలు” — అంటారు: రోగానికి కారణం (హేతువు), లక్షణాలు (లింగం), చికిత్స (ఔషధం) — ఆరోగ్యవంతులకూ రోగులకూ కూడా. దీర్ఘ అధ్యయనంతో పదునెక్కిన బుద్ధితో భరద్వాజుడు అంతా త్వరగా గ్రహించాడని గ్రంథం చెబుతుంది."],
   ["dyk", "🌿", "Āyur-veda means “the knowledge of life,” not just “the knowledge of disease.” It teaches how to stay well — food, sleep, seasons, daily routine — as much as how to cure.", "ఆయుర్వేదం అంటే “ఆయువు గురించిన జ్ఞానం” — కేవలం “రోగాల జ్ఞానం” కాదు. ఎలా నయం చేయాలో ఎంతగా నేర్పుతుందో, ఆహారం, నిద్ర, ఋతువులు, దినచర్యల ద్వారా ఆరోగ్యంగా ఎలా ఉండాలో కూడా అంతగా నేర్పుతుంది."]
  ],
  [
   ["h", "From Bharadvāja to Caraka", "భరద్వాజుని నుండి చరకుని వరకు"],
   ["p", "Bharadvāja came back down and taught the sages, and they lived long, healthy lives. Among those who received the knowledge was {punarvasu|Punarvasu Ātreya}, who taught it to six disciples: {agnivesha|Agniveśa}, Bheḍa, Jatūkarṇa, Parāśara, Hārīta and Kṣārapāṇi. Agniveśa was the first to write it down as a book. Much later the physician Caraka revised and enlarged Agniveśa's work — and that is the Caraka Saṃhitā we have today.", "భరద్వాజుడు తిరిగి వచ్చి మహర్షులకు నేర్పాడు; వారు దీర్ఘకాలం ఆరోగ్యంగా జీవించారు. ఆ జ్ఞానం పొందినవారిలో {punarvasu|పునర్వసు ఆత్రేయుడు} ఒకడు; ఆయన దాన్ని ఆరుగురు శిష్యులకు నేర్పాడు: {agnivesha|అగ్నివేశుడు}, భేడుడు, జాతూకర్ణుడు, పరాశరుడు, హారీతుడు, క్షారపాణి. దాన్ని గ్రంథంగా మొదట రాసినవాడు అగ్నివేశుడు. చాలా కాలం తర్వాత చరకుడు అనే వైద్యుడు అగ్నివేశుని గ్రంథాన్ని సవరించి విస్తరించాడు — అదే ఈ రోజు మన దగ్గర ఉన్న చరక సంహిత."],
   ["p", "The other great book of Āyurveda, the Suśruta Saṃhitā, tells a different line: there the knowledge comes to earth through Dhanvantari, born as King Divodāsa of Kāśī, who teaches surgery to Suśruta. The two schools each remember their own first teacher — for the physicians of Caraka's school, it is Bharadvāja.", "ఆయుర్వేదపు మరో మహాగ్రంథమైన సుశ్రుత సంహిత వేరే పరంపర చెబుతుంది: అక్కడ ఆ జ్ఞానం కాశీ రాజు దివోదాసునిగా పుట్టిన ధన్వంతరి ద్వారా భూమికి వస్తుంది; ఆయన సుశ్రుతునికి శస్త్రచికిత్స నేర్పుతాడు. రెండు సంప్రదాయాలూ తమ తమ ఆదిగురువును గుర్తుంచుకుంటాయి — చరక సంప్రదాయ వైద్యులకు ఆ గురువు భరద్వాజుడు."],
   ["sglink", "The Great Family — Āyurveda in Aṅgiras' line", "మహా వంశం — అంగిరస వంశంలో ఆయుర్వేదం", "an-12"],
   ["src", "Caraka Saṃhitā, Sūtrasthāna, chapter 1 (Dīrghañjīvitīya — “On Long Life”): the sages' assembly, Bharadvāja's journey to Indra, the tri-sūtra, and the line Punarvasu Ātreya → Agniveśa and five others. Suśruta Saṃhitā, Sūtrasthāna, chapter 1 (Dhanvantari as Divodāsa of Kāśī).", "చరక సంహిత, సూత్రస్థానం, మొదటి అధ్యాయం (దీర్ఘంజీవితీయం — “దీర్ఘాయువు గురించి”): మహర్షుల సమావేశం, ఇంద్రుని దగ్గరికి భరద్వాజుని ప్రయాణం, త్రిసూత్రం, పునర్వసు ఆత్రేయుని నుండి అగ్నివేశుడు మొదలైన ఆరుగురికి పరంపర. సుశ్రుత సంహిత, సూత్రస్థానం, మొదటి అధ్యాయం (కాశీ రాజు దివోదాసునిగా ధన్వంతరి)."]
  ]
 ],
 remember: [
  ["When disease spread, the sages met in the Himālayas, and {bharadvajamuni|Bharadvāja} volunteered to go to {indra|Indra}.", "రోగాలు వ్యాపించినప్పుడు మహర్షులు హిమాలయాలలో సమావేశమయ్యారు; {indra|ఇంద్రుని} దగ్గరికి వెళ్ళడానికి {bharadvajamuni|భరద్వాజుడు} ముందుకు వచ్చాడు."],
  ["Indra taught him the three threads of Āyurveda: cause, sign and remedy.", "ఇంద్రుడు ఆయనకు ఆయుర్వేదపు మూడు సూత్రాలు నేర్పాడు: కారణం, లక్షణం, ఔషధం."],
  ["Through {punarvasu|Punarvasu Ātreya} and {agnivesha|Agniveśa} it came down to the Caraka Saṃhitā.", "{punarvasu|పునర్వసు ఆత్రేయుడు}, {agnivesha|అగ్నివేశుల} ద్వారా అది చరక సంహితగా మనకు వచ్చింది."]
 ],
 think: ["Bharadvāja said “Send me” when a hard journey had to be made for others. When did you last volunteer for something difficult that would help other people?", "ఇతరుల కోసం కష్టమైన ప్రయాణం చేయాల్సి వచ్చినప్పుడు భరద్వాజుడు “నన్ను పంపండి” అన్నాడు. ఇతరులకు ఉపయోగపడే కష్టమైన పనికి మీరు చివరిసారి ఎప్పుడు ముందుకు వచ్చారు?"]
},
{
 id: "bd-7", sage: "bharadvaja", n: 7, order: 1307, date: "2026-10-23",
 title: "Rāma at the Meeting of the Rivers", titleTe: "సంగమం దగ్గర శ్రీరాముడు",
 src: "Vālmīki Rāmāyaṇa, Ayodhyā and Yuddha Kāṇḍas",
 who: ["bharadvajamuni", "rama", "sita", "lakshmana", "guha", "hanuman", "bharata"],
 pages: [
  [
   ["p", "In the Rāmāyaṇa, {bharadvajamuni|Bharadvāja} is no longer a young seer of hymns but a great old teacher. His āśrama stands at Prayāga, where the white Gaṅgā and the dark Yamunā meet. Around him live many disciples; deer and birds wander fearlessly among the huts; the smoke of his sacred fire can be seen from far away.", "రామాయణంలో {bharadvajamuni|భరద్వాజుడు} సూక్తాలు దర్శించే యువ ఋషి కాదు — గొప్ప వృద్ధ గురువు. తెల్లని గంగ, నల్లని యమున కలిసే ప్రయాగలో ఆయన ఆశ్రమం ఉంది. ఆయన చుట్టూ ఎందరో శిష్యులు; కుటీరాల మధ్య జింకలూ పక్షులూ నిర్భయంగా తిరుగుతాయి; ఆయన యజ్ఞాగ్ని పొగ చాలా దూరం నుండే కనిపిస్తుంది."],
   ["p", "In the first days of their exile, after {guha|Guha} had ferried them across the Gaṅgā, {rama|Rāma}, {sita|Sītā} and {lakshmana|Lakṣmaṇa} walked through the forest towards the confluence. Seeing that smoke at evening, Rāma said, “We must be near Bharadvāja's āśrama.”", "{guha|గుహుడు} గంగను దాటించిన తర్వాత, వనవాసపు ప్రారంభ రోజుల్లో {rama|శ్రీరాముడు}, {sita|సీతాదేవి}, {lakshmana|లక్ష్మణుడు} అడవి గుండా సంగమం వైపు నడిచారు. సాయంత్రం ఆ పొగ చూసి రాముడు అన్నాడు: “మనం భరద్వాజుని ఆశ్రమానికి దగ్గరలో ఉన్నాం.”"]
  ],
  [
   ["h", "“I Have Been Waiting for You”", "“నీ కోసమే ఎదురుచూస్తున్నాను”"],
   ["p", "The three exiles stood at a respectful distance and bowed. Rāma said, “We are the sons of Daśaratha — I am Rāma, this is Lakṣmaṇa, and this is Sītā, princess of Videha, who followed me into the forest. By our father's command we are going to live in the forest as hermits.”", "ముగ్గురూ గౌరవంగా దూరంగా నిలబడి నమస్కరించారు. రాముడు అన్నాడు: “మేము దశరథుని కుమారులం — నేను రాముణ్ణి, ఇతను లక్ష్మణుడు, ఈమె నా వెంట అడవికి వచ్చిన విదేహ రాకుమారి సీత. తండ్రిగారి ఆజ్ఞ మేరకు మునులవలె అడవిలో జీవించడానికి వెళ్తున్నాం.”"],
   ["p", "Bharadvāja welcomed them with water, honey, fruits and roots, and gave them a place to rest. “Rāma,” he said, “I have been waiting a long time to see you. I have heard how you were sent away though you did nothing wrong. This place where the two rivers meet is holy and pleasant. Stay here with me.”", "భరద్వాజుడు వారికి నీళ్ళు, తేనె, పండ్లు, దుంపలతో స్వాగతం పలికి విశ్రాంతికి చోటిచ్చాడు. “రామా,” అన్నాడు, “నిన్ను చూడాలని చాలా కాలంగా ఎదురుచూస్తున్నాను. ఏ తప్పూ చేయకుండానే నిన్ను పంపేశారని విన్నాను. రెండు నదులు కలిసే ఈ ప్రదేశం పవిత్రమైనది, మనోహరమైనది. నాతో ఇక్కడే ఉండు.”"],
   ["p", "Rāma thanked him but said, “Revered sir, this is too near to Ayodhyā. People of the city and the countryside will keep coming here to see Sītā and me. Please tell us of a lonely place where we can live quietly, and where Sītā will be happy.”", "రాముడు కృతజ్ఞతలు చెప్పి అన్నాడు: “పూజ్యులారా, ఇది అయోధ్యకు చాలా దగ్గర. మమ్మల్ని చూడడానికి నగరవాసులూ పల్లెవాసులూ ఇక్కడికి వస్తూనే ఉంటారు. మేము ప్రశాంతంగా జీవించగలిగే, సీత సంతోషంగా ఉండగలిగే ఏకాంత ప్రదేశం చెప్పండి.”"]
  ],
  [
   ["h", "The Way to Citrakūṭa", "చిత్రకూటానికి దారి"],
   ["p", "“Ten krośas from here,” said Bharadvāja, “there is a holy hill called Citrakūṭa. Many great sages have lived there. Its peaks are lovely, peacocks call in its woods, elephants roam its slopes. As long as a person looks upon its peaks, the mind turns only to good, never to evil. Live there.”", "“ఇక్కడి నుండి పది క్రోసుల దూరంలో,” అన్నాడు భరద్వాజుడు, “చిత్రకూటం అనే పవిత్ర పర్వతం ఉంది. ఎందరో మహర్షులు అక్కడ నివసించారు. దాని శిఖరాలు మనోహరమైనవి, అడవుల్లో నెమళ్ళు కూస్తాయి, వాలుల్లో ఏనుగులు తిరుగుతాయి. దాని శిఖరాలను చూస్తున్నంత సేపూ మనస్సు మంచివైపే మళ్ళుతుంది, చెడువైపు ఎప్పుడూ కాదు. అక్కడ నివసించు.”"],
   ["p", "The next morning he blessed them like a father blessing his own children, and told them exactly how to go: cross the Yamunā on a raft, pray at the great banyan tree called Śyāma on the far bank, and walk on. They followed his directions and reached Citrakūṭa, where they built their hut.", "మరుసటి ఉదయం సొంత పిల్లలను దీవించే తండ్రిలా వారిని దీవించి, ఎలా వెళ్ళాలో సరిగ్గా చెప్పాడు: తెప్ప మీద యమునను దాటండి, అవతలి ఒడ్డున శ్యామం అనే మహా వటవృక్షం దగ్గర ప్రార్థించండి, ముందుకు నడవండి. ఆయన చెప్పినట్టే వెళ్ళి వారు చిత్రకూటం చేరి కుటీరం కట్టుకున్నారు."],
   ["link", "Read it in the Rāmāyaṇa: Bharadvāja and Citrakūṭa", "రామాయణంలో చదవండి: భరద్వాజుడు, చిత్రకూటం", "ayodhya-10"]
  ],
  [
   ["h", "Fourteen Years Later", "పద్నాలుగు సంవత్సరాల తర్వాత"],
   ["p", "Bharadvāja saw Rāma once more — at the very end of the exile. Flying home from Laṅkā in the Puṣpaka chariot, Rāma brought it down at Prayāga on the fifth day of the bright fortnight, exactly fourteen years after he had left. He bowed to the old sage and asked for news of Ayodhyā.", "భరద్వాజుడు రాముణ్ణి మళ్ళీ ఒకసారి చూశాడు — వనవాసం చివరలో. లంక నుండి పుష్పక విమానంలో తిరిగి వస్తూ, సరిగ్గా పద్నాలుగు సంవత్సరాలు పూర్తయిన శుక్ల పంచమి నాడు రాముడు ప్రయాగలో దిగాడు. వృద్ధ మునికి నమస్కరించి అయోధ్య వార్తలు అడిగాడు."],
   ["p", "“{bharata|Bharata} is well,” said Bharadvāja. “He wears bark and matted hair, keeps your sandals on the throne, and rules only in your name, waiting for you.” Then he told Rāma that, through his tapas, he had seen everything that happened in the forest and in Laṅkā. He asked Rāma to stay the night, and as a parting gift a boon was granted: all along the road to Ayodhyā the trees would bear flowers and fruit out of season, so that Rāma's vānara friends would not go hungry. That night Rāma sent {hanuman|Hanumān} ahead to tell Bharata he was coming.", "“{bharata|భరతుడు} క్షేమంగా ఉన్నాడు,” అన్నాడు భరద్వాజుడు. “నారచీరలు, జటలు ధరించి, నీ పాదుకలను సింహాసనంపై ఉంచి, నీ పేరుతోనే పాలిస్తూ నీ కోసం ఎదురుచూస్తున్నాడు.” అడవిలో, లంకలో జరిగినదంతా తన తపశ్శక్తితో చూశానని రామునికి చెప్పాడు. ఆ రాత్రి ఉండమని కోరాడు; వీడ్కోలు కానుకగా ఒక వరం లభించింది: అయోధ్యకు వెళ్ళే దారి పొడవునా చెట్లు కాలం కాని కాలంలో కూడా పూలతో, పండ్లతో నిండిపోతాయి — రాముని వానర మిత్రులు ఆకలితో ఉండకుండా. ఆ రాత్రే తాను వస్తున్నానని భరతునికి చెప్పడానికి రాముడు {hanuman|హనుమంతుణ్ణి} ముందుగా పంపాడు."],
   ["link", "Read it in the Rāmāyaṇa: The Flight Home in the Puṣpaka", "రామాయణంలో చదవండి: పుష్పకంలో తిరుగు ప్రయాణం", "yuddha-27"],
   ["dyk", "🪷", "Much later, Tulasīdās begins his Hindi Rāmcaritmānas at Prayāga too: there the sage Yājñavalkya tells the whole story of Rāma to Bharadvāja during the Māgha bathing festival. That is a later telling, not Vālmīki's — but it shows how Prayāga and Bharadvāja stayed joined in people's minds. A Bharadvāja Āśrama is still shown in Prayāgrāj today.", "చాలా కాలం తర్వాత తులసీదాసు తన హిందీ రామచరితమానస్‌ను కూడా ప్రయాగలోనే ప్రారంభిస్తాడు: అక్కడ మాఘ స్నానాల సమయంలో యాజ్ఞవల్క్య మహర్షి భరద్వాజునికి రామకథ మొత్తం చెబుతాడు. అది వాల్మీకిది కాదు, తర్వాతి కథనం — కానీ ప్రజల మనసుల్లో ప్రయాగా, భరద్వాజుడూ ఎంతగా కలిసిపోయారో చూపిస్తుంది. ఈ రోజుకీ ప్రయాగ్‌రాజ్‌లో భరద్వాజ ఆశ్రమం చూపిస్తారు."],
   ["src", "Vālmīki Rāmāyaṇa, Ayodhyā Kāṇḍa (the arrival at Prayāga, Bharadvāja's welcome and his directions to Citrakūṭa); Yuddha Kāṇḍa (the return in the Puṣpaka, the stop at Bharadvāja's āśrama and the boon of the fruiting trees). Tulasīdās, Rāmcaritmānas, Bāla Kāṇḍa (sixteenth century).", "వాల్మీకి రామాయణం, అయోధ్యాకాండ (ప్రయాగ చేరడం, భరద్వాజుని ఆతిథ్యం, చిత్రకూటానికి దారి); యుద్ధకాండ (పుష్పకంలో తిరుగు ప్రయాణం, భరద్వాజ ఆశ్రమంలో విడిది, ఫలించే చెట్ల వరం). తులసీదాసు, రామచరితమానస్, బాలకాండ (పదహారవ శతాబ్దం)."]
  ]
 ],
 remember: [
  ["{bharadvajamuni|Bharadvāja}'s āśrama stood at Prayāga, where the Gaṅgā meets the Yamunā.", "{bharadvajamuni|భరద్వాజుని} ఆశ్రమం గంగ, యమున కలిసే ప్రయాగలో ఉండేది."],
  ["He welcomed {rama|Rāma}, Sītā and Lakṣmaṇa and sent them to the holy hill of Citrakūṭa.", "ఆయన {rama|శ్రీరాముణ్ణి}, సీతను, లక్ష్మణుణ్ణి ఆహ్వానించి పవిత్ర చిత్రకూట పర్వతానికి పంపాడు."],
  ["Fourteen years later Rāma stopped there again on his way home, and the trees to Ayodhyā bore fruit out of season.", "పద్నాలుగు సంవత్సరాల తర్వాత తిరిగి వెళ్తూ రాముడు మళ్ళీ అక్కడ ఆగాడు; అయోధ్యకు దారిలో చెట్లు అకాలంలో ఫలించాయి."]
 ],
 think: ["Bharadvāja said that looking at Citrakūṭa's peaks turns the mind to good. Is there a place that calms your mind and makes you want to be better?", "చిత్రకూట శిఖరాలను చూస్తే మనస్సు మంచివైపు మళ్ళుతుందని భరద్వాజుడు అన్నాడు. మీ మనస్సును శాంతపరిచి, మంచిగా ఉండాలనిపించే ప్రదేశం మీకు ఏదైనా ఉందా?"]
},
{
 id: "bd-8", sage: "bharadvaja", n: 8, order: 1308, date: "2026-10-23",
 title: "A Feast for an Army — Bharata Tested", titleTe: "సైన్యానికి విందు — భరతుని పరీక్ష",
 src: "Vālmīki Rāmāyaṇa, Ayodhyā Kāṇḍa",
 who: ["bharadvajamuni", "bharata", "vasishtha", "kausalya", "sumitra", "kaikeyi", "rama"],
 pages: [
  [
   ["p", "Some weeks after Rāma left, a great army came marching along the Gaṅgā: elephants, horses, chariots, foot-soldiers, and all the people of Ayodhyā. At its head was {bharata|Bharata}. Daśaratha had died of grief, and Bharata, refusing the throne his mother had won for him, was going into the forest to bring Rāma home.", "రాముడు వెళ్ళిన కొన్ని వారాల తర్వాత గంగ వెంబడి ఒక మహా సైన్యం కదిలి వచ్చింది: ఏనుగులు, గుర్రాలు, రథాలు, కాల్బలం, అయోధ్య ప్రజలందరూ. దాని ముందు {bharata|భరతుడు}. దశరథుడు దుఃఖంతో చనిపోయాడు; తల్లి తన కోసం సంపాదించిన సింహాసనాన్ని నిరాకరించి, రాముణ్ణి ఇంటికి తీసుకురావడానికి భరతుడు అడవికి వెళ్తున్నాడు."],
   ["p", "Near Prayāga, Bharata halted the army a krośa away so that it would not disturb the hermitage. He took off his royal ornaments and walked, in simple clothes, with the family guru {vasishtha|Vasiṣṭha}, to Bharadvāja's āśrama.", "ప్రయాగ దగ్గర, ఆశ్రమానికి ఆటంకం కలగకూడదని భరతుడు సైన్యాన్ని ఒక క్రోసు దూరంలో ఆపాడు. రాజాభరణాలు తీసేసి, సాధారణ వస్త్రాలతో కులగురువు {vasishtha|వసిష్ఠునితో} కలిసి భరద్వాజుని ఆశ్రమానికి నడిచి వెళ్ళాడు."]
  ],
  [
   ["h", "A Hard Question", "కఠినమైన ప్రశ్న"],
   ["p", "{bharadvajamuni|Bharadvāja} received them kindly and asked after the kingdom. Then he looked straight at Bharata. “You are ruling now. Why have you come all this way with an army? I hope you do not mean harm to Rāma — so that you can enjoy the kingdom without a rival?”", "{bharadvajamuni|భరద్వాజుడు} వారిని ఆదరంగా స్వీకరించి రాజ్య క్షేమం అడిగాడు. తర్వాత భరతుని వైపు సూటిగా చూశాడు. “ఇప్పుడు నువ్వు రాజువు. సైన్యంతో ఇంత దూరం ఎందుకు వచ్చావు? ఎదురులేకుండా రాజ్యం అనుభవించడానికి రామునికి కీడు చేయాలని నీ ఉద్దేశం కాదు కదా?”"],
   ["p", "The words struck Bharata like a blow. His eyes filled with tears. “If even you think this of me, revered sir, then I am truly lost. I did not want any of this, and I do not approve of what my mother did. I have come to fall at Rāma's feet and take him back to Ayodhyā. Tell me where he is.”", "ఆ మాటలు భరతునికి దెబ్బలా తగిలాయి. కళ్ళు నీళ్ళతో నిండిపోయాయి. “పూజ్యులారా, మీరు కూడా నన్ను ఇలా అనుకుంటే నేను నిజంగా నశించినట్టే. ఇదేదీ నేను కోరుకోలేదు; మా అమ్మ చేసినదాన్ని నేను ఒప్పుకోను. రాముని పాదాలపై పడి ఆయనను అయోధ్యకు తీసుకెళ్ళడానికి వచ్చాను. ఆయన ఎక్కడున్నారో చెప్పండి.”"],
   ["p", "Bharadvāja smiled. “I knew your heart already, Bharata. You are a true son of the Raghu family. I asked only so that your goodness would be seen by all, and your fame would grow. Rāma is on Citrakūṭa. But stay here tonight with your ministers and your army; tomorrow you can go.”", "భరద్వాజుడు చిరునవ్వు నవ్వాడు. “భరతా, నీ మనస్సు నాకు ముందే తెలుసు. నువ్వు నిజమైన రఘువంశీయుడివి. నీ మంచితనం అందరికీ కనిపించాలని, నీ కీర్తి పెరగాలని మాత్రమే అడిగాను. రాముడు చిత్రకూటంలో ఉన్నాడు. ఈ రాత్రి నీ మంత్రులతో, సైన్యంతో ఇక్కడే ఉండు; రేపు వెళ్ళవచ్చు.”"]
  ],
  [
   ["h", "The Feast", "విందు"],
   ["p", "“I wish to feed your whole army,” said Bharadvāja. Bharata hesitated — how could a forest sage feed so many thousands? But Bharadvāja entered his fire-hall, sipped water three times, and called on the gods: Viśvakarmā the divine builder, Indra, Yama, Varuṇa and Kubera, the rivers of earth and sky, the gandharvas and the apsaras. “I wish to honour my guests. Prepare a welcome!”", "“నీ సైన్యమంతటికీ భోజనం పెట్టాలని ఉంది,” అన్నాడు భరద్వాజుడు. భరతుడు సందేహించాడు — అడవిలో ఉండే ముని ఇన్ని వేల మందికి ఎలా పెట్టగలడు? కానీ భరద్వాజుడు అగ్నిశాలలోకి వెళ్ళి మూడుసార్లు ఆచమనం చేసి దేవతలను ఆహ్వానించాడు: దేవశిల్పి విశ్వకర్మ, ఇంద్రుడు, యముడు, వరుణుడు, కుబేరుడు, భూమి ఆకాశాల నదులు, గంధర్వులు, అప్సరసలు. “నా అతిథులను సత్కరించాలని ఉంది. స్వాగతానికి ఏర్పాట్లు చేయండి!”"],
   ["p", "At once a cool, sweet wind began to blow, and flowers rained down. The plain filled with shining mansions, stables for elephants and horses, soft beds and seats. Streams flowed with sweet drinks; there were heaps of rice, lakes of curd and milk, piles of fruit and sweets, pots of honey. Gandharvas sang and apsaras danced. The soldiers ate and rested and laughed, “We will never go back to Ayodhyā — and we won't go to the forest either! This is heaven!”", "వెంటనే చల్లని, తియ్యని గాలి వీచింది; పూలవాన కురిసింది. మైదానం మెరిసే భవనాలతో, ఏనుగుల గుర్రాల శాలలతో, మెత్తని పడకలు ఆసనాలతో నిండిపోయింది. తియ్యని పానీయాలు ప్రవాహాలుగా పారాయి; అన్నపు రాశులు, పెరుగు పాల సరస్సులు, పండ్లు మిఠాయిల గుట్టలు, తేనె కుండలు. గంధర్వులు పాడారు, అప్సరసలు నాట్యం చేశారు. సైనికులు తిని, విశ్రాంతి తీసుకుని నవ్వుకున్నారు: “మనం ఇక అయోధ్యకు వెళ్ళం — అడవికీ వెళ్ళం! ఇదే స్వర్గం!”"],
   ["p", "Only Bharata, thinking of Rāma sleeping on the ground, took no pleasure in any of it. And at dawn the mansions, the music and the rivers of drink all vanished like a dream.", "నేల మీద పడుకుని ఉన్న రాముణ్ణి తలుచుకుంటూ భరతుడు మాత్రం దేనిలోనూ ఆనందం పొందలేదు. తెల్లవారేసరికి భవనాలూ, సంగీతమూ, పానీయాల ప్రవాహాలూ అన్నీ కలలా మాయమయ్యాయి."]
  ],
  [
   ["h", "“Do Not Blame Kaikeyī”", "“కైకేయిని నిందించవద్దు”"],
   ["p", "In the morning Bharadvāja asked Bharata to introduce the queens. Bharata pointed to each in turn: {kausalya|Kausalyā}, thin from fasting and grief, Rāma's mother; {sumitra|Sumitrā}, mother of Lakṣmaṇa and Śatrughna. Then, with bitterness, he pointed to his own mother: “And this is {kaikeyi|Kaikeyī} — cruel, proud, the cause of all our sorrow, the woman who drove Rāma out and killed my father.”", "ఉదయం రాణులను పరిచయం చేయమని భరద్వాజుడు భరతుణ్ణి అడిగాడు. భరతుడు ఒక్కొక్కరినీ చూపించాడు: ఉపవాసంతో, దుఃఖంతో చిక్కిపోయిన రాముని తల్లి {kausalya|కౌసల్య}; లక్ష్మణ శత్రుఘ్నుల తల్లి {sumitra|సుమిత్ర}. తర్వాత చేదుగా తన తల్లిని చూపించాడు: “ఈమె {kaikeyi|కైకేయి} — క్రూరురాలు, గర్విష్ఠి, మా దుఃఖానికంతటికీ కారణం; రాముణ్ణి వెళ్ళగొట్టి నా తండ్రి చావుకు కారణమైనది.”"],
   ["p", "Bharadvāja answered gently but firmly: “Bharata, you must not find fault with Kaikeyī. This exile of Rāma will end in happiness — for the gods, for the sages, and for the whole world.” The seer saw further than the grieving son: without the exile there would be no meeting with the sages of the forest, no end to Rāvaṇa. Then Bharadvāja blessed them, and Bharata went on to Citrakūṭa.", "భరద్వాజుడు మృదువుగా కానీ దృఢంగా జవాబిచ్చాడు: “భరతా, కైకేయిని నిందించకూడదు. రాముని ఈ వనవాసం సుఖంతోనే ముగుస్తుంది — దేవతలకూ, మహర్షులకూ, లోకమంతటికీ.” దుఃఖంలో ఉన్న కొడుకు కంటే ఆ ఋషి దూరంగా చూశాడు: వనవాసం లేకపోతే అరణ్యంలోని మునులను కలవడం ఉండదు, రావణుని అంతమూ ఉండదు. తర్వాత భరద్వాజుడు వారిని దీవించాడు; భరతుడు చిత్రకూటానికి వెళ్ళాడు."],
   ["link", "Read it in the Rāmāyaṇa: Bharadvāja's Feast", "రామాయణంలో చదవండి: భరద్వాజుని ఆతిథ్యం", "ayodhya-16"],
   ["src", "Vālmīki Rāmāyaṇa, Ayodhyā Kāṇḍa: Bharata's arrival at Prayāga, Bharadvāja's question, the feast summoned from the gods, the introduction of the queens and Bharadvāja's words about Kaikeyī.", "వాల్మీకి రామాయణం, అయోధ్యాకాండ: భరతుడు ప్రయాగ చేరడం, భరద్వాజుని ప్రశ్న, దేవతలను పిలిచి ఇచ్చిన విందు, రాణుల పరిచయం, కైకేయి గురించి భరద్వాజుని మాటలు."]
  ]
 ],
 remember: [
  ["{bharadvajamuni|Bharadvāja} tested {bharata|Bharata} with a hard question, then praised his true heart.", "{bharadvajamuni|భరద్వాజుడు} కఠినమైన ప్రశ్నతో {bharata|భరతుణ్ణి} పరీక్షించి, తర్వాత అతని నిజాయితీగల మనస్సును మెచ్చుకున్నాడు."],
  ["By calling on the gods he feasted Bharata's whole army for one night.", "దేవతలను ఆహ్వానించి భరతుని సైన్యమంతటికీ ఒక రాత్రి విందు చేశాడు."],
  ["He told Bharata not to blame {kaikeyi|Kaikeyī}: Rāma's exile would end in good for the world.", "{kaikeyi|కైకేయిని} నిందించవద్దని భరతునికి చెప్పాడు: రాముని వనవాసం లోకానికి మేలుతోనే ముగుస్తుంది."]
 ],
 think: ["Bharadvāja asked Bharata a hard question so that his goodness would be seen by all. Is it ever kind to ask someone a hard question?", "భరతుని మంచితనం అందరికీ కనిపించాలని భరద్వాజుడు అతన్ని కఠినమైన ప్రశ్న అడిగాడు. ఎవరినైనా కఠినమైన ప్రశ్న అడగడం కూడా దయ కాగలదా?"]
},
{
 id: "bd-9", sage: "bharadvaja", n: 9, order: 1309, date: "2026-10-23",
 title: "Droṇa, Śrutāvatī and Devavarṇinī — the Sage's Children", titleTe: "ద్రోణుడు, శ్రుతావతి, దేవవర్ణిని — ముని సంతానం",
 src: "Mahābhārata, Ādi, Droṇa and Śalya Parvas · Rāmāyaṇa, Uttara",
 who: ["bharadvajamuni", "ghritachi", "drona", "prishata", "drupada", "agnivesha", "shrutavati", "devavarnini", "vishravas", "kubera"],
 pages: [
  [
   ["p", "The Mahābhārata places {bharadvajamuni|Bharadvāja}'s āśrama at Gaṅgādvāra — “the gate of the Gaṅgā,” where the river leaves the mountains, today's Haridvāra. There he lived a life of strict vows. One day he went down to the river to bathe and saw the apsaras {ghritachi|Ghṛtācī}, who had just bathed there herself. A gust of wind blew her garment aside.", "మహాభారతం {bharadvajamuni|భరద్వాజుని} ఆశ్రమాన్ని గంగాద్వారంలో — “గంగ ద్వారం,” నది కొండల నుండి బయటికి వచ్చే చోటు, నేటి హరిద్వారంలో — ఉంచుతుంది. అక్కడ ఆయన కఠిన వ్రతాలతో జీవించాడు. ఒక రోజు స్నానానికి నదికి వెళ్ళి, అప్పుడే స్నానం చేసి వస్తున్న {ghritachi|ఘృతాచి} అనే అప్సరసను చూశాడు. ఒక గాలి విసురుకు ఆమె వస్త్రం పక్కకు జరిగింది."],
   ["p", "At the sight of her, desire rose in the old sage, and his seed fell. He did not let it go to waste: he placed it in a *droṇa*, a wooden vessel. From that vessel a son was born, and he was named {drona|Droṇa}, “born of the vessel.” The Mahābhārata tells this plainly, as it tells the births of many great people — not in the usual way, but as they happened.", "ఆమెను చూసి ఆ వృద్ధ మునిలో కామం కలిగింది; ఆయన వీర్యం స్ఖలించింది. దాన్ని వృథా పోనివ్వకుండా ఒక *ద్రోణం* — చెక్క కలశం — లో ఉంచాడు. ఆ కలశం నుండి ఒక కుమారుడు పుట్టాడు; అతనికి {drona|ద్రోణుడు} — “కలశం నుండి పుట్టినవాడు” — అని పేరు పెట్టారు. ఎందరో మహనీయుల జననాలను చెప్పినట్టే మహాభారతం దీన్నీ సూటిగా చెబుతుంది — సాధారణ పద్ధతిలో కాదు, జరిగినట్టే."],
   ["dyk", "🏺", "Droṇa was “born from a vessel,” Kṛpa and Kṛpī were found in a clump of reeds, and Vasiṣṭha and Agastya came from a pot. The epics love strange births — they mark a child as someone unusual.", "ద్రోణుడు “కలశం నుండి” పుట్టాడు; కృపుడూ కృపీ రెల్లుపొదలో దొరికారు; వసిష్ఠుడూ అగస్త్యుడూ కుంభం నుండి వచ్చారు. విచిత్రమైన జననాలంటే ఇతిహాసాలకు ఇష్టం — ఆ బిడ్డ అసాధారణుడని అవి సూచిస్తాయి."]
  ],
  [
   ["h", "Two Boys in One Āśrama", "ఒకే ఆశ్రమంలో ఇద్దరు బాలురు"],
   ["p", "Bharadvāja had a friend, {prishata|Pṛṣata}, king of Pāñcāla. Pṛṣata's son {drupada|Drupada} came to Bharadvāja's āśrama and studied there every day beside young Droṇa. The two boys played and learned together and became dear friends. Drupada used to say, “When I am king, half my kingdom will be yours.”", "భరద్వాజునికి పాంచాల రాజు {prishata|పృషతుడు} మిత్రుడు. పృషతుని కుమారుడు {drupada|ద్రుపదుడు} భరద్వాజుని ఆశ్రమానికి వచ్చి రోజూ చిన్నారి ద్రోణుని పక్కనే చదువుకునేవాడు. ఇద్దరూ కలిసి ఆడుకున్నారు, నేర్చుకున్నారు, ప్రాణ స్నేహితులయ్యారు. “నేను రాజునైనప్పుడు నా రాజ్యంలో సగం నీదే” అని ద్రుపదుడు అనేవాడు."],
   ["p", "Bharadvāja also knew the science of weapons. He gave the great fire-weapon, the Āgneya astra, to his disciple {agnivesha|Agniveśa}; and Agniveśa, out of respect for his guru, taught it to his guru's son Droṇa. So the teacher of Arjuna learned his first divine weapon from his father's student.", "భరద్వాజునికి అస్త్రవిద్య కూడా తెలుసు. మహా అగ్ని అస్త్రమైన ఆగ్నేయాస్త్రాన్ని తన శిష్యుడు {agnivesha|అగ్నివేశునికి} ఇచ్చాడు; గురువుపై గౌరవంతో అగ్నివేశుడు దాన్ని గురుపుత్రుడైన ద్రోణునికి నేర్పాడు. అలా అర్జునుని గురువు తన మొదటి దివ్యాస్త్రాన్ని తన తండ్రి శిష్యుని నుండి నేర్చుకున్నాడు."],
   ["p", "In time Bharadvāja left this world. Droṇa stayed on at his father's āśrama doing tapas, until he married Kṛpī. What came after — the broken friendship with Drupada, the teaching of the Kuru princes, the great war — is the Mahābhārata's story of Droṇa.", "కాలక్రమంలో భరద్వాజుడు ఈ లోకాన్ని విడిచాడు. కృపిని పెళ్ళి చేసుకునే వరకూ ద్రోణుడు తండ్రి ఆశ్రమంలోనే తపస్సు చేస్తూ ఉన్నాడు. ఆ తర్వాతిది — ద్రుపదునితో తెగిన స్నేహం, కురు రాకుమారులకు విద్య, మహాయుద్ధం — మహాభారతంలోని ద్రోణుని కథ."]
  ],
  [
   ["h", "The Father Comes for His Son", "కొడుకు కోసం వచ్చిన తండ్రి"],
   ["p", "Bharadvāja appears once more in Droṇa's life — at its end. On the fifteenth day of the Kurukṣetra war, Droṇa, fighting for the Kauravas, was burning whole ranks of soldiers with the brahmāstra, a weapon he should never have used against ordinary fighters. Then a company of great sages came through the sky in subtle bodies — Viśvāmitra, Jamadagni, Bharadvāja, Gautama, Vasiṣṭha and others — to take him away.", "ద్రోణుని జీవితంలో భరద్వాజుడు మరొకసారి కనిపిస్తాడు — దాని చివరలో. కురుక్షేత్ర యుద్ధంలో పదిహేనవ రోజున కౌరవుల పక్షాన పోరాడుతున్న ద్రోణుడు, సాధారణ సైనికులపై ఎప్పుడూ ప్రయోగించకూడని బ్రహ్మాస్త్రంతో సైనిక పంక్తులను దహిస్తున్నాడు. అప్పుడు సూక్ష్మ శరీరాలతో మహర్షుల సమూహం ఆకాశం నుండి వచ్చింది — విశ్వామిత్రుడు, జమదగ్ని, భరద్వాజుడు, గౌతముడు, వసిష్ఠుడు మొదలైనవారు — ఆయనను తీసుకెళ్ళడానికి."],
   ["p", "“You are fighting against dharma,” they told him. “You have burned with the brahmāstra men who do not know such weapons. This is not right for a brāhmaṇa. Your time has come. Lay down your weapons.” Soon after, hearing the false news that his son Aśvatthāmā was dead, Droṇa put down his bow, sat in yoga on his chariot, and his spirit rose like a bright light to heaven — before Dhṛṣṭadyumna's sword struck his body.", "“నువ్వు అధర్మంగా పోరాడుతున్నావు,” అన్నారు వారు. “అలాంటి అస్త్రాలు తెలియని మనుషులను బ్రహ్మాస్త్రంతో దహించావు. బ్రాహ్మణునికి ఇది తగదు. నీ సమయం వచ్చింది. ఆయుధాలు విడిచిపెట్టు.” కొద్ది సేపటికే, కొడుకు అశ్వత్థామ చనిపోయాడనే అబద్ధపు వార్త విని, ద్రోణుడు ధనుస్సు కింద పెట్టి రథంపైనే యోగంలో కూర్చున్నాడు; ధృష్టద్యుమ్నుని ఖడ్గం ఆయన శరీరాన్ని తాకకముందే ఆయన ఆత్మ ప్రకాశవంతమైన వెలుగులా స్వర్గానికి వెళ్ళిపోయింది."]
  ],
  [
   ["h", "Two Daughters", "ఇద్దరు కుమార్తెలు"],
   ["p", "The Mahābhārata names a daughter too: {shrutavati|Śrutāvatī}, born to Bharadvāja and Ghṛtācī. She did fierce tapas on the bank of the Sarasvatī, wishing for Indra as her husband. Indra came to test her disguised as the sage Vasiṣṭha, gave her some jujube fruits, and asked her to cook them for him. She cooked all day, but by Indra's power the fruits never softened. When the firewood ran out, she put her own feet into the fire and kept cooking, without a word of complaint. Indra showed himself, delighted, and took her to heaven as his wife. The place was named Badarapācana, “where the jujubes were cooked.”", "మహాభారతం ఒక కుమార్తె పేరు కూడా చెబుతుంది: భరద్వాజుడు, ఘృతాచిలకు పుట్టిన {shrutavati|శ్రుతావతి}. ఇంద్రుణ్ణి భర్తగా కోరుకుంటూ ఆమె సరస్వతీ తీరంలో కఠోర తపస్సు చేసింది. పరీక్షించడానికి ఇంద్రుడు వసిష్ఠ మహర్షి వేషంలో వచ్చి, కొన్ని రేగుపళ్ళు ఇచ్చి తన కోసం వండమన్నాడు. ఆమె రోజంతా వండింది; కానీ ఇంద్రుని మాయ వల్ల పళ్ళు మెత్తబడనే లేదు. కట్టెలు అయిపోతే తన కాళ్ళనే నిప్పులో పెట్టి, ఒక్క మాట కూడా ఫిర్యాదు చేయకుండా వండుతూనే ఉంది. ఇంద్రుడు సంతోషించి తన నిజరూపం చూపి, ఆమెను భార్యగా స్వర్గానికి తీసుకెళ్ళాడు. ఆ ప్రదేశానికి బదరపాచనం — “రేగుపళ్ళు వండిన చోటు” — అని పేరు వచ్చింది."],
   ["p", "The Rāmāyaṇa names another daughter, {devavarnini|Devavarṇinī}. Bharadvāja gave her in marriage to the sage {vishravas|Viśravas}, son of Pulastya, and their son was Vaiśravaṇa — {kubera|Kubera}, the lord of wealth. So Bharadvāja was grandfather both to Kubera and, through Droṇa, to Aśvatthāmā.", "రామాయణం మరో కుమార్తె పేరు చెబుతుంది — {devavarnini|దేవవర్ణిని}. పులస్త్యుని కుమారుడైన {vishravas|విశ్రవసు} మహర్షికి భరద్వాజుడు ఆమెను ఇచ్చి పెళ్ళి చేశాడు; వారి కుమారుడు వైశ్రవణుడు — ధనాధిపతి {kubera|కుబేరుడు}. అంటే భరద్వాజుడు కుబేరునికీ, ద్రోణుని ద్వారా అశ్వత్థామకూ తాత."],
   ["link", "Read it in the Rāmāyaṇa: Kubera's Birth", "రామాయణంలో చదవండి: కుబేరుని జననం", "uttara-1"],
   ["src", "Mahābhārata, Ādi Parva (Droṇa's birth at Gaṅgādvāra; Pṛṣata and Drupada; the Āgneya weapon through Agniveśa); Droṇa Parva (the sages call Droṇa to lay down his arms; his death); Śalya Parva, Balarāma's pilgrimage along the Sarasvatī (Śrutāvatī and Badarapācana). Vālmīki Rāmāyaṇa, Uttara Kāṇḍa (Devavarṇinī, Viśravas and Kubera's birth).", "మహాభారతం, ఆదిపర్వం (గంగాద్వారంలో ద్రోణ జననం; పృషతుడు, ద్రుపదుడు; అగ్నివేశుని ద్వారా ఆగ్నేయాస్త్రం); ద్రోణపర్వం (ఆయుధాలు విడవమని మహర్షులు ద్రోణుని పిలవడం; ఆయన మరణం); శల్యపర్వం, సరస్వతీ తీరంలో బలరాముని తీర్థయాత్ర (శ్రుతావతి, బదరపాచనం). వాల్మీకి రామాయణం, ఉత్తరకాండ (దేవవర్ణిని, విశ్రవసుడు, కుబేర జననం)."]
  ]
 ],
 remember: [
  ["{drona|Droṇa} was born from a vessel after {bharadvajamuni|Bharadvāja} saw the apsaras {ghritachi|Ghṛtācī}; he grew up with {drupada|Drupada} in his father's āśrama.", "{bharadvajamuni|భరద్వాజుడు} {ghritachi|ఘృతాచి} అప్సరసను చూసిన తర్వాత {drona|ద్రోణుడు} కలశం నుండి పుట్టాడు; తండ్రి ఆశ్రమంలో {drupada|ద్రుపదునితో} కలిసి పెరిగాడు."],
  ["At Kurukṣetra, Bharadvāja and other sages came to tell Droṇa to lay down his arms.", "కురుక్షేత్రంలో భరద్వాజుడు మొదలైన మహర్షులు ఆయుధాలు విడవమని ద్రోణునికి చెప్పడానికి వచ్చారు."],
  ["His daughter {shrutavati|Śrutāvatī} won Indra by her tapas; his daughter {devavarnini|Devavarṇinī} was Kubera's mother.", "ఆయన కుమార్తె {shrutavati|శ్రుతావతి} తపస్సుతో ఇంద్రుణ్ణి పొందింది; మరో కుమార్తె {devavarnini|దేవవర్ణిని} కుబేరుని తల్లి."]
 ],
 think: ["Bharadvāja's son Droṇa became a great teacher but also used a terrible weapon wrongly. Can a good teacher still make wrong choices? What should we learn from such a person?", "భరద్వాజుని కుమారుడు ద్రోణుడు గొప్ప గురువయ్యాడు; కానీ భయంకరమైన అస్త్రాన్ని తప్పుగా కూడా వాడాడు. మంచి గురువు కూడా తప్పుడు నిర్ణయాలు తీసుకోవచ్చా? అలాంటి వ్యక్తి నుండి మనం ఏం నేర్చుకోవాలి?"]
},
{
 id: "bd-10", sage: "bharadvaja", n: 10, order: 1310, date: "2026-10-23",
 title: "Yavakrīta — the Son Who Wanted Knowledge Without a Teacher", titleTe: "యవక్రీతుడు — గురువు లేకుండా జ్ఞానం కోరిన కొడుకు",
 src: "Mahābhārata, Āraṇyaka Parva (Lomaśa's tīrtha stories)",
 who: ["bharadvajamuni", "yavakri", "raibhya", "paravasu", "arvavasu", "indra", "lomasha", "surya"],
 pages: [
  [
   ["p", "The saddest story of {bharadvajamuni|Bharadvāja}'s life is told in the Mahābhārata by the sage {lomasha|Lomaśa}, as he leads the Pāṇḍavas on pilgrimage. They had reached the old āśrama of {raibhya|Raibhya}, and Lomaśa told them what had once happened there.", "{bharadvajamuni|భరద్వాజుని} జీవితంలోని అత్యంత విషాదకరమైన కథను మహాభారతంలో {lomasha|లోమశ} మహర్షి పాండవులను తీర్థయాత్రకు తీసుకువెళ్తూ చెబుతాడు. వారు {raibhya|రైభ్యుని} పాత ఆశ్రమానికి చేరారు; అక్కడ ఒకప్పుడు ఏం జరిగిందో లోమశుడు చెప్పాడు."],
   ["p", "Bharadvāja and Raibhya were dear friends and lived in neighbouring āśramas. Raibhya and his two sons, {paravasu|Parāvasu} and {arvavasu|Arvāvasu}, were famous scholars, and people honoured them everywhere. Bharadvāja was a great ascetic, but his son {yavakri|Yavakrīta} had no such learning — and he burned with envy at the honour given to Raibhya's family.", "భరద్వాజుడూ రైభ్యుడూ ప్రాణ స్నేహితులు; పక్కపక్క ఆశ్రమాల్లో ఉండేవారు. రైభ్యుడు, ఆయన ఇద్దరు కొడుకులు {paravasu|పరావసుడు}, {arvavasu|అర్వావసుడు} ప్రసిద్ధ పండితులు; అంతటా వారికి గౌరవం. భరద్వాజుడు గొప్ప తపస్వి; కానీ ఆయన కొడుకు {yavakri|యవక్రీతునికి} అంత విద్య లేదు — రైభ్యుని కుటుంబానికి దక్కే గౌరవం చూసి అసూయతో రగిలిపోయాడు."]
  ],
  [
   ["h", "Sand Into the Gaṅgā", "గంగలో ఇసుక"],
   ["p", "Yavakrīta decided he would have the Vedas without years of study. He did terrible tapas, scorching his body before a blazing fire, until {indra|Indra} came. “What do you want?” “Let the Vedas appear in me, all of them, without a teacher — knowledge no one else has.” Indra said, “That is not the way. Go and learn from a teacher.” But Yavakrīta only made his tapas fiercer.", "ఏళ్ళ తరబడి అధ్యయనం లేకుండానే వేదాలు పొందాలని యవక్రీతుడు నిర్ణయించుకున్నాడు. మండే అగ్ని ముందు శరీరాన్ని కాల్చుకుంటూ భయంకరమైన తపస్సు చేశాడు; {indra|ఇంద్రుడు} వచ్చాడు. “ఏం కావాలి?” “గురువు లేకుండానే వేదాలన్నీ నాలో ప్రకాశించాలి — మరెవరికీ లేని జ్ఞానం.” ఇంద్రుడు అన్నాడు: “అది మార్గం కాదు. వెళ్ళి గురువు దగ్గర నేర్చుకో.” కానీ యవక్రీతుడు తపస్సును ఇంకా తీవ్రం చేశాడు."],
   ["p", "Then Indra came again, as a feeble old brāhmaṇa, and sat on the bank of the Gaṅgā throwing handfuls of sand into the water. “What are you doing?” laughed Yavakrīta. “Building a bridge across the Gaṅgā,” said the old man, “so people can cross easily.” “You fool! You will never dam this great river with sand.” The old man looked at him. “As foolish as your plan to know the Vedas without study.”", "అప్పుడు ఇంద్రుడు బలహీనమైన వృద్ధ బ్రాహ్మణుని రూపంలో మళ్ళీ వచ్చి, గంగ ఒడ్డున కూర్చుని పిడికెడు పిడికెడు ఇసుక నీళ్ళలోకి విసురుతున్నాడు. “ఏం చేస్తున్నావు?” అని నవ్వాడు యవక్రీతుడు. “గంగకు అడ్డంగా వంతెన కడుతున్నాను,” అన్నాడు ముసలాయన, “ప్రజలు సులభంగా దాటడానికి.” “ఓరి మూర్ఖుడా! ఇసుకతో ఈ మహానదిని ఎప్పటికీ ఆపలేవు.” ముసలాయన అతని వైపు చూశాడు. “అధ్యయనం లేకుండా వేదాలు తెలుసుకోవాలనే నీ ప్రయత్నం కూడా అంతే మూర్ఖమైనది.”"],
   ["p", "Still Yavakrīta would not give up. At last Indra granted the boon: “You and your father will know the Vedas.” Yavakrīta ran home triumphant.", "అయినా యవక్రీతుడు పట్టు విడవలేదు. చివరికి ఇంద్రుడు వరం ఇచ్చాడు: “నీకూ నీ తండ్రికీ వేదాలు తెలుస్తాయి.” యవక్రీతుడు విజయగర్వంతో ఇంటికి పరుగెత్తాడు."]
  ],
  [
   ["h", "A Father's Warning", "తండ్రి హెచ్చరిక"],
   ["p", "Bharadvāja was not happy. “Son, a boon won this way brings pride, and pride destroys. Raibhya is a great man, and quick to anger. Do not offend him.” He told an old story: a sage's son, Medhāvī, was granted a boon that he would live as long as a certain mountain stood. Sure he could not die, he insulted everyone — until a sage named Dhanuṣākṣa had the mountain broken by buffaloes, and the boy fell dead with it.", "భరద్వాజుడు సంతోషించలేదు. “బాబూ, ఇలా పొందిన వరం గర్వాన్ని తెస్తుంది; గర్వం నాశనం చేస్తుంది. రైభ్యుడు గొప్పవాడు, త్వరగా కోపపడతాడు. ఆయనను బాధపెట్టకు.” ఒక పాత కథ చెప్పాడు: మేధావి అనే ముని కుమారునికి ఒక పర్వతం నిలిచి ఉన్నంత కాలం బతుకుతాడని వరం లభించింది. తనకు చావు లేదనుకుని అందరినీ అవమానించాడు — చివరికి ధనుషాక్షుడు అనే ముని దున్నపోతులతో ఆ పర్వతాన్ని పగలగొట్టించాడు; దానితో పాటే ఆ బాలుడూ పడి చనిపోయాడు."],
   ["p", "Yavakrīta did not listen. He grew arrogant and began to insult other sages. Then, one spring, he came upon Parāvasu's wife — Raibhya's daughter-in-law — alone in the āśrama grove, and he pressed himself on her shamelessly. Frightened of his anger and his new powers, she could not drive him off; she escaped from him and went home in tears.", "యవక్రీతుడు వినలేదు. అహంకారంతో ఇతర మునులను అవమానించడం మొదలుపెట్టాడు. ఒక వసంత కాలంలో ఆశ్రమ ఉద్యానవనంలో ఒంటరిగా ఉన్న పరావసుని భార్యను — రైభ్యుని కోడలిని — చూసి సిగ్గులేకుండా ఆమెను బలవంతపెట్టాడు. అతని కోపానికీ కొత్త శక్తులకూ భయపడి ఆమె అతన్ని గట్టిగా తరిమికొట్టలేకపోయింది; ఎలాగో తప్పించుకుని ఏడుస్తూ ఇంటికి వెళ్ళింది."]
  ],
  [
   ["h", "Raibhya's Anger", "రైభ్యుని కోపం"],
   ["p", "When Raibhya saw his daughter-in-law weeping and heard what had happened, his anger blazed. He tore out a lock of his matted hair and offered it into the fire with mantras: from it rose a woman exactly like his daughter-in-law. He offered a second lock: from it rose a terrible rākṣasa. “Kill Yavakrīta,” he commanded.", "ఏడుస్తున్న కోడలిని చూసి జరిగినది విన్న రైభ్యుని కోపం భగ్గుమంది. తన జటలో ఒక పాయను పెరికి మంత్రాలతో అగ్నిలో వేశాడు: దాని నుండి సరిగ్గా తన కోడలి లాంటి స్త్రీ పుట్టింది. రెండో పాయను వేశాడు: భయంకరమైన రాక్షసుడు పుట్టాడు. “యవక్రీతుణ్ణి చంపండి” అని ఆజ్ఞాపించాడు."],
   ["p", "The woman went to Yavakrīta, charmed him, and slipped away his water-pot. Without water to purify himself he could not use his mantras. The rākṣasa rushed at him with a spear. Yavakrīta ran to a lake — it was dry. Every river he ran to had dried up. At last he fled to his father's fire-hall, but the blind servant who guarded the door held him back, and there, at his father's door, the rākṣasa killed him.", "ఆ స్త్రీ యవక్రీతుని దగ్గరికి వెళ్ళి అతన్ని మోహింపజేసి, అతని కమండలాన్ని దొంగిలించింది. శుద్ధి చేసుకోవడానికి నీళ్ళు లేక అతని మంత్రాలు పనిచేయలేదు. రాక్షసుడు శూలంతో మీదికి దూకాడు. యవక్రీతుడు ఒక సరస్సుకు పరుగెత్తాడు — అది ఎండిపోయింది. ఏ నదికి వెళ్ళినా అది ఎండిపోయింది. చివరికి తండ్రి అగ్నిశాలకు పారిపోయాడు; కానీ ద్వారం కాపలా కాసే గుడ్డి సేవకుడు అతన్ని అడ్డగించాడు; అక్కడే, తండ్రి గుమ్మం దగ్గరే, రాక్షసుడు అతన్ని చంపేశాడు."],
   ["p", "Bharadvāja came home and found his son dead. His grief was beyond bearing. In that grief he cursed his old friend: “As Raibhya has taken my only son from me for no fault of mine, so his own eldest son will kill him.” Then, at once, he was ashamed: “I have cursed my friend.” He cremated his son, and, unable to live with his sorrow, he entered the same fire and gave up his life.", "భరద్వాజుడు ఇంటికి వచ్చి కొడుకు చనిపోయి ఉండడం చూశాడు. ఆయన దుఃఖం భరించలేనిది. ఆ దుఃఖంలో తన పాత మిత్రుణ్ణి శపించాడు: “నా తప్పు లేకుండానే రైభ్యుడు నా కొడుకును నా నుండి తీసుకున్నాడు; అలాగే అతని పెద్ద కొడుకే అతన్ని చంపుతాడు.” వెంటనే సిగ్గుపడ్డాడు: “నా మిత్రుణ్ణి శపించాను.” కొడుకుకు దహనసంస్కారం చేసి, ఆ దుఃఖంతో బతకలేక అదే అగ్నిలో ప్రవేశించి ప్రాణం విడిచాడు."]
  ],
  [
   ["h", "The Brother Who Took the Blame", "నేరం తనపై వేసుకున్న తమ్ముడు"],
   ["p", "The curse came true. Raibhya's sons were serving as priests at King Bṛhadyumna's great sacrifice. One night Parāvasu came home through the forest and, in the dark, saw a figure wrapped in a black deerskin. Thinking it was a wild animal, he struck — and killed his own father. He performed the funeral rites, then went to his younger brother. “You do the penance for this killing of a brāhmaṇa for me, and I will carry on the king's sacrifice.” Arvāvasu agreed and did the hard penance.", "శాపం నిజమైంది. రైభ్యుని కొడుకులు బృహద్ద్యుమ్న రాజు మహాయజ్ఞంలో పురోహితులుగా ఉన్నారు. ఒక రాత్రి పరావసుడు అడవి గుండా ఇంటికి వస్తూ, చీకటిలో నల్లని జింకచర్మం కప్పుకున్న ఆకారాన్ని చూశాడు. అడవి జంతువనుకుని కొట్టాడు — సొంత తండ్రినే చంపేశాడు. అంత్యక్రియలు చేసి తమ్ముని దగ్గరికి వెళ్ళాడు: “బ్రహ్మహత్యకు ప్రాయశ్చిత్తం నా బదులు నువ్వు చెయ్యి; రాజు యజ్ఞాన్ని నేను కొనసాగిస్తాను.” అర్వావసుడు ఒప్పుకుని కఠిన ప్రాయశ్చిత్తం చేశాడు."],
   ["p", "But when Arvāvasu returned to the sacrifice, Parāvasu cried out before the king, “This man is a brāhmaṇa-killer! Do not let him in!” Arvāvasu was driven out, though he swore he had done no wrong. He went to the forest and worshipped the {surya|Sun}. The gods were pleased and offered him boons. He asked: that his father live again; that his brother be freed from the sin; that his father forget the killing; and that Bharadvāja and Yavakrīta live again too. All was granted.", "కానీ అర్వావసుడు యజ్ఞానికి తిరిగి వచ్చినప్పుడు పరావసుడు రాజు ముందు అరిచాడు: “ఇతను బ్రహ్మహంతకుడు! లోపలికి రానివ్వకండి!” తాను ఏ తప్పూ చేయలేదని ప్రమాణం చేసినా అర్వావసుణ్ణి వెళ్ళగొట్టారు. అతను అడవికి వెళ్ళి {surya|సూర్యుణ్ణి} ఆరాధించాడు. దేవతలు సంతోషించి వరాలు ఇస్తామన్నారు. అతను అడిగాడు: తన తండ్రి మళ్ళీ బతకాలి; అన్న పాపం నుండి విముక్తుడవ్వాలి; తండ్రి ఆ హత్యను మరిచిపోవాలి; భరద్వాజుడూ యవక్రీతుడూ కూడా మళ్ళీ బతకాలి. అన్నీ లభించాయి."],
   ["p", "Yavakrīta, alive again, asked the gods: “I knew the Vedas and kept my vows. How could Raibhya kill me?” The gods answered: “You learned the Vedas without a teacher, without effort. Raibhya learned them through long years of hardship, serving his gurus. That is why his power was greater.” Lomaśa ended the story and told the Pāṇḍavas: bathe here, and be free of sin.", "మళ్ళీ బతికిన యవక్రీతుడు దేవతలను అడిగాడు: “నాకు వేదాలు తెలుసు, వ్రతాలు పాటించాను. రైభ్యుడు నన్ను ఎలా చంపగలిగాడు?” దేవతలు జవాబిచ్చారు: “నువ్వు గురువు లేకుండా, శ్రమ లేకుండా వేదాలు నేర్చుకున్నావు. రైభ్యుడు ఏళ్ళ తరబడి కష్టపడి, గురువులకు సేవ చేసి నేర్చుకున్నాడు. అందుకే ఆయన శక్తి ఎక్కువ.” లోమశుడు కథ ముగించి పాండవులతో అన్నాడు: ఇక్కడ స్నానం చేయండి, పాపాల నుండి విముక్తులవ్వండి."],
   ["src", "Mahābhārata, Āraṇyaka (Vana) Parva, the tīrtha-yātrā section: Lomaśa tells the story of Yavakrīta, Raibhya, Bharadvāja, Parāvasu and Arvāvasu at Raibhya's āśrama (including Indra's sand bridge, the tale of Medhāvī and Dhanuṣākṣa, and King Bṛhadyumna's sacrifice).", "మహాభారతం, ఆరణ్యక (వన) పర్వం, తీర్థయాత్రా భాగం: రైభ్యుని ఆశ్రమం దగ్గర లోమశుడు యవక్రీతుడు, రైభ్యుడు, భరద్వాజుడు, పరావసుడు, అర్వావసుల కథ చెబుతాడు (ఇంద్రుని ఇసుక వంతెన, మేధావి–ధనుషాక్షుల కథ, బృహద్ద్యుమ్న రాజు యజ్ఞం సహా)."]
  ]
 ],
 remember: [
  ["{yavakri|Yavakrīta} forced the Vedas from Indra by tapas, ignored his father's warning, and wronged Raibhya's daughter-in-law.", "{yavakri|యవక్రీతుడు} తపస్సుతో ఇంద్రుని నుండి బలవంతంగా వేదాలు పొంది, తండ్రి హెచ్చరికను పట్టించుకోకుండా, రైభ్యుని కోడలికి అన్యాయం చేశాడు."],
  ["{raibhya|Raibhya}'s rākṣasa killed him; {bharadvajamuni|Bharadvāja} cursed Raibhya in grief and gave up his life in the fire.", "{raibhya|రైభ్యుని} రాక్షసుడు అతన్ని చంపాడు; దుఃఖంలో {bharadvajamuni|భరద్వాజుడు} రైభ్యుణ్ణి శపించి అగ్నిలో ప్రాణం విడిచాడు."],
  ["{arvavasu|Arvāvasu}'s goodness won back the lives of all three — and the gods said learning needs a teacher.", "{arvavasu|అర్వావసుని} మంచితనం ముగ్గురికీ ప్రాణాలు తిరిగి తెచ్చింది — విద్యకు గురువు కావాలని దేవతలు చెప్పారు."]
 ],
 think: ["Yavakrīta wanted knowledge quickly, without a teacher or hard work. Why do you think knowledge gained the slow way is stronger?", "యవక్రీతుడు గురువు లేకుండా, శ్రమ లేకుండా త్వరగా జ్ఞానం కావాలనుకున్నాడు. నెమ్మదిగా, కష్టపడి పొందిన జ్ఞానం ఎందుకు బలమైనదని మీరు అనుకుంటున్నారు?"]
},
{
 id: "bd-11", sage: "bharadvaja", n: 11, order: 1311, date: "2026-10-23",
 title: "The Questioner — and a Name That Lives On", titleTe: "ప్రశ్నించేవాడు — చిరంజీవిగా నిలిచిన పేరు",
 src: "Mahābhārata, Śānti Parva · Yoga Vāsiṣṭha · Upaniṣads · living tradition",
 who: ["bharadvajamuni", "bhrigu", "valmiki", "bharadvaja", "sukesha", "vasishtha", "rama"],
 pages: [
  [
   ["p", "Through all his stories, {bharadvajamuni|Bharadvāja} is above all a questioner. He asked Indra for one more life to study; he asked Indra for medicine. And in the Mahābhārata, when the dying Bhīṣma teaches Yudhiṣṭhira, he recalls a long conversation in which Bharadvāja asks {bhrigu|Bhṛgu} the biggest questions of all: how was the world made? What is the life inside the body, and where does it go? How did people come to be divided into varṇas?", "తన కథలన్నిటిలో {bharadvajamuni|భరద్వాజుడు} అన్నిటికంటే ముందు ప్రశ్నించేవాడు. చదువుకోవడానికి ఇంకొక జీవితం కావాలని ఇంద్రుణ్ణి అడిగాడు; వైద్యం కావాలని ఇంద్రుణ్ణి అడిగాడు. మహాభారతంలో అంపశయ్యపై ఉన్న భీష్ముడు యుధిష్ఠిరునికి బోధిస్తూ, భరద్వాజుడు {bhrigu|భృగువును} అతి పెద్ద ప్రశ్నలు అడిగిన సుదీర్ఘ సంభాషణను గుర్తుచేస్తాడు: ఈ లోకం ఎలా పుట్టింది? శరీరంలోని ప్రాణం ఏమిటి, అది ఎక్కడికి వెళ్తుంది? మనుషులు వర్ణాలుగా ఎలా విభజించబడ్డారు?"],
   ["sglink", "Bhṛgu answers Bharadvāja", "భరద్వాజునికి భృగువు జవాబులు", "bh-10"],
   ["dyk", "👂", "The Bṛhadāraṇyaka Upaniṣad links the seven great sages with the openings of the head. The two ears, it says, are Gautama and Bharadvāja. How fitting that the great questioner should be an ear — always listening.", "బృహదారణ్యక ఉపనిషత్తు సప్తర్షులను తలలోని రంధ్రాలతో అనుసంధానిస్తుంది. రెండు చెవులూ గౌతముడు, భరద్వాజుడు అని చెబుతుంది. గొప్ప ప్రశ్నకర్త చెవి కావడం ఎంత తగినదో — ఎప్పుడూ వింటూ ఉండేది."]
  ],
  [
   ["h", "Vālmīki's Bharadvāja", "వాల్మీకి శిష్యుడైన భరద్వాజుడు"],
   ["p", "The Rāmāyaṇa also has a Bharadvāja who is {valmiki|Vālmīki}'s own disciple. He carried his teacher's water-pot to the Tamasā on the morning the first śloka was born, and was the first to learn it by heart. And the Yoga Vāsiṣṭha is told as Vālmīki's answer to this disciple: {bharadvaja|Bharadvāja} asks how one can cross the ocean of saṃsāra, and Vālmīki answers by telling him the whole conversation in which {vasishtha|Vasiṣṭha} taught young {rama|Rāma}.", "రామాయణంలో వాల్మీకి సొంత శిష్యుడైన భరద్వాజుడు కూడా ఉన్నాడు. మొదటి శ్లోకం పుట్టిన ఉదయం గురువు కమండలాన్ని మోసుకుని తమసా నదికి వెళ్ళినదీ, ఆ శ్లోకాన్ని మొదట కంఠస్థం చేసినదీ ఆయనే. యోగవాసిష్ఠం కూడా ఈ శిష్యునికి {valmiki|వాల్మీకి} ఇచ్చిన సమాధానంగానే చెప్పబడింది: సంసార సాగరాన్ని ఎలా దాటాలని {bharadvaja|భరద్వాజుడు} అడుగుతాడు; {vasishtha|వసిష్ఠుడు} యువ {rama|శ్రీరామునికి} బోధించిన సంభాషణ మొత్తాన్ని చెప్పి వాల్మీకి జవాబిస్తాడు."],
   ["p", "Is this the same Bharadvāja as the old sage of Prayāga? The texts do not say. Bharadvāja is also a family name — every member of the line can be called Bhāradvāja — and the Rāmāyaṇa itself shows the disciple and the master of Prayāga as two different people. Some later readers take them as one; most simply leave the question open.", "ఈయన ప్రయాగలోని వృద్ధ మునేనా? గ్రంథాలు చెప్పవు. భరద్వాజ అనేది వంశనామం కూడా — ఆ వంశంలో ప్రతి ఒక్కరినీ భారద్వాజుడు అనవచ్చు — రామాయణమే శిష్యుణ్ణి, ప్రయాగ గురువును ఇద్దరు వేర్వేరు వ్యక్తులుగా చూపిస్తుంది. తర్వాతి కొందరు పాఠకులు ఇద్దరినీ ఒక్కరిగా భావిస్తారు; చాలామంది ఆ ప్రశ్నను అలాగే వదిలేస్తారు."],
   ["sglink", "Vālmīki, Bharadvāja and the krauñca's cry", "వాల్మీకి, భరద్వాజుడు, క్రౌంచ పక్షి రోదన", "vl-4"]
  ],
  [
   ["h", "The Family of Questioners", "ప్రశ్నించేవారి వంశం"],
   ["p", "The habit of asking ran in the family. In the Muṇḍaka Upaniṣad, the knowledge of Brahman passes through a teacher called Bhāradvāja Satyavāha. In the Praśna Upaniṣad — the “Upaniṣad of Questions” — the first of the six seekers is {sukesha|Sukeśā Bhāradvāja}.", "ప్రశ్నించే అలవాటు ఆ వంశంలోనే ఉంది. ముండకోపనిషత్తులో బ్రహ్మవిద్య భారద్వాజ సత్యవాహుడు అనే గురువు ద్వారా వస్తుంది. ప్రశ్నోపనిషత్తులో — “ప్రశ్నల ఉపనిషత్తు” — ఆరుగురు జిజ్ఞాసువులలో మొదటివాడు {sukesha|సుకేశ భారద్వాజుడు}."],
   ["p", "Sukeśā's own question shows the family's honesty. A prince of Kosala once asked him about “the Person of sixteen parts.” Sukeśā answered, “I do not know him. If I knew, why would I not tell you? A man who speaks untruth dries up to the very root.” The prince left in silence — and Sukeśā went to find a teacher who did know. To say “I do not know” is the first step of every real question.", "సుకేశుని సొంత ప్రశ్నే ఆ వంశపు నిజాయితీని చూపిస్తుంది. ఒకసారి కోసల రాకుమారుడు ఆయనను “పదహారు కళల పురుషుని” గురించి అడిగాడు. సుకేశుడు జవాబిచ్చాడు: “నాకు ఆయన తెలియదు. తెలిస్తే నీకు ఎందుకు చెప్పను? అసత్యం పలికేవాడు వేళ్ళతో సహా ఎండిపోతాడు.” రాకుమారుడు మౌనంగా వెళ్ళిపోయాడు — సుకేశుడు తెలిసిన గురువును వెతుక్కుంటూ వెళ్ళాడు. “నాకు తెలియదు” అనడమే ప్రతి నిజమైన ప్రశ్నకూ మొదటి మెట్టు."],
   ["sglink", "Śaunaka's Question — the Muṇḍaka Upaniṣad", "శౌనకుని ప్రశ్న — ముండకోపనిషత్తు", "an-8"]
  ],
  [
   ["h", "A Name That Lives On", "చిరంజీవిగా నిలిచిన పేరు"],
   ["p", "In the Purāṇas' list of the seven sages of our present age — the age of Vaivasvata Manu — Bharadvāja shines beside Kaśyapa, Atri, Vasiṣṭha, Viśvāmitra, Gautama and Jamadagni. Ritual books of the Taittirīya school still bear his family's name: the Bhāradvāja Śrauta and Gṛhya Sūtras. And the Bharadvāja gotra is one of the most common among Telugu families today; every time a child of that gotra recites “Āṅgirasa, Bārhaspatya, Bhāradvāja,” the abandoned baby of the first chapter is remembered.", "మన ప్రస్తుత యుగమైన వైవస్వత మన్వంతరపు సప్తర్షుల పురాణ జాబితాలో కశ్యపుడు, అత్రి, వసిష్ఠుడు, విశ్వామిత్రుడు, గౌతముడు, జమదగ్నిలతో పాటు భరద్వాజుడు ప్రకాశిస్తాడు. తైత్తిరీయ శాఖకు చెందిన కర్మకాండ గ్రంథాలు ఈ రోజుకీ ఆయన వంశ నామాన్ని మోస్తున్నాయి: భారద్వాజ శ్రౌత, గృహ్య సూత్రాలు. తెలుగు కుటుంబాలలో ఈ రోజు అత్యంత సాధారణమైన గోత్రాలలో భరద్వాజ గోత్రం ఒకటి; ఆ గోత్రపు బిడ్డ “ఆంగీరస, బార్హస్పత్య, భారద్వాజ” అని చెప్పిన ప్రతిసారీ మొదటి అధ్యాయంలోని ఆ వదిలేసిన పసిబిడ్డ గుర్తుకొస్తాడు."],
   ["dyk", "✈️", "In the twentieth century a book on flying machines, the “Vaimānika Śāstra,” was published under Bharadvāja's name. It is not an ancient text: it was dictated in the early 1900s, and engineers at the Indian Institute of Science who studied it in 1974 found that its machines could not fly. Bharadvāja's real gifts — hymns, medicine and questions — need no such help.", "ఇరవయ్యవ శతాబ్దంలో విమానాల గురించిన “వైమానిక శాస్త్రం” అనే పుస్తకం భరద్వాజుని పేరుతో ప్రచురించబడింది. అది ప్రాచీన గ్రంథం కాదు: 1900ల ప్రారంభంలో చెప్పి రాయించినది; 1974లో దాన్ని పరిశీలించిన భారతీయ విజ్ఞాన సంస్థ (IISc) ఇంజనీర్లు అందులోని యంత్రాలు ఎగరలేవని తేల్చారు. భరద్వాజుని నిజమైన కానుకలకు — సూక్తాలు, వైద్యం, ప్రశ్నలు — అలాంటి సహాయం అక్కర్లేదు."],
   ["p", "Abandoned at birth, he was raised by storm gods, adopted by an emperor, saw a book of the Veda, studied for three lifetimes, carried medicine down from heaven, sheltered Rāma and fed Bharata's army, fathered Droṇa, and lost his own son to pride. Few sages lived so many lives in one. The child his parents threw away became the man a whole people still claim as their ancestor.", "పుట్టగానే వదిలేయబడ్డాడు; తుఫాను దేవతలు పెంచారు; చక్రవర్తి దత్తత తీసుకున్నాడు; వేదంలోని ఒక మండలాన్ని దర్శించాడు; మూడు జన్మలు అధ్యయనం చేశాడు; స్వర్గం నుండి వైద్యాన్ని తెచ్చాడు; రామునికి ఆశ్రయమిచ్చి, భరతుని సైన్యానికి అన్నం పెట్టాడు; ద్రోణునికి తండ్రయ్యాడు; గర్వం వల్ల సొంత కొడుకును కోల్పోయాడు. ఒకే జీవితంలో ఇన్ని జీవితాలు గడిపిన మునులు అరుదు. తల్లిదండ్రులు విసిరేసిన ఆ బిడ్డ, ఒక జాతి మొత్తం ఈ రోజుకీ తమ పూర్వీకుడని చెప్పుకునే మహర్షి అయ్యాడు."],
   ["src", "Mahābhārata, Śānti Parva, Mokṣadharma (the dialogue of Bhṛgu and Bharadvāja); Vālmīki Rāmāyaṇa, Bāla Kāṇḍa (Vālmīki's disciple at the Tamasā); Yoga Vāsiṣṭha, opening frame (Vālmīki and Bharadvāja); Bṛhadāraṇyaka Upaniṣad 2.2.4 (the ears as Gautama and Bharadvāja); Muṇḍaka Upaniṣad 1.1.2; Praśna Upaniṣad 1.1 and 6.1 (Sukeśā Bhāradvāja); Viṣṇu Purāṇa 3.1 (the seven sages of this age). The Vaimānika Śāstra is a twentieth-century work.", "మహాభారతం, శాంతిపర్వం, మోక్షధర్మం (భృగు–భరద్వాజ సంవాదం); వాల్మీకి రామాయణం, బాలకాండ (తమసా తీరంలో వాల్మీకి శిష్యుడు); యోగవాసిష్ఠం, ఆరంభ కథ (వాల్మీకి, భరద్వాజుడు); బృహదారణ్యక ఉపనిషత్తు 2.2.4 (చెవులు గౌతముడు, భరద్వాజుడు); ముండకోపనిషత్తు 1.1.2; ప్రశ్నోపనిషత్తు 1.1, 6.1 (సుకేశ భారద్వాజుడు); విష్ణు పురాణం 3.1 (ఈ యుగపు సప్తర్షులు). వైమానిక శాస్త్రం ఇరవయ్యవ శతాబ్దపు రచన."]
  ]
 ],
 remember: [
  ["{bharadvajamuni|Bharadvāja} asked {bhrigu|Bhṛgu} the great questions of life in the Mahābhārata's Śānti Parva.", "మహాభారతం శాంతిపర్వంలో {bharadvajamuni|భరద్వాజుడు} {bhrigu|భృగువును} జీవితపు గొప్ప ప్రశ్నలు అడిగాడు."],
  ["Vālmīki's disciple Bharadvāja hears the Yoga Vāsiṣṭha; whether he is the sage of Prayāga, the texts do not say.", "వాల్మీకి శిష్యుడైన భరద్వాజుడు యోగవాసిష్ఠాన్ని వింటాడు; ఆయన ప్రయాగ మునేనా అని గ్రంథాలు చెప్పవు."],
  ["He is one of the seven sages of our age, and the Bharadvāja gotra lives on in countless families.", "ఆయన మన యుగపు సప్తర్షులలో ఒకరు; భరద్వాజ గోత్రం లెక్కలేనన్ని కుటుంబాలలో కొనసాగుతోంది."]
 ],
 think: ["Sukeśā Bhāradvāja said “I do not know” to a prince rather than invent an answer. Why is it sometimes hard to say “I do not know”? Why is it brave?", "సమాధానం కల్పించడం కంటే సుకేశ భారద్వాజుడు రాకుమారునితో “నాకు తెలియదు” అన్నాడు. “నాకు తెలియదు” అనడం కొన్నిసార్లు ఎందుకు కష్టం? అది ఎందుకు ధైర్యం?"]
}
]);
